<div class="cdn-book-reader-content">
    <div class="lexile-version active" data-lexile="original" data-lexile-label="Original (1320L)">
        <div class="chapter">
<h2 class="smallprint" title="The First Part of the Con­ten­tion of The Two Fam­ovs Houses of Yorke &amp; Lan­cas­ter, with the death of the good Duke Humph­rey." id="idd">
The First Part of the Con­ten­tion of The
Two Famovs Houses of <i>Yorke</i> &amp; <i>Lancaster</i>, with the death of the
good Duke <i>Humphrey</i>.</h2></div>

<div class="right toppada"><small><a href="#idtoc" class="pginternal">toc</a></small></div>

<div class="sd-schg">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> I.
<span class="dnavigatenf">daa</span></h3>

<i>Enter at one doore, King</i> <span class="smcaps">H<span>ENRY</span></span> <i>the sixt, and</i> <span class="smcaps">H<span>UMPHREY</span></span> <i>Duke of</i> <span class="smcaps">G<span>LOSTER</span>,</span> <i>the Duke of</i> <span class="smcaps">S<span>OMMERSET</span>,</span> <i>the Duke of</i> <span class="smcaps">B<span>UCKINGHAM</span>,</span> <i>Cardinall</i> <span class="smcaps">B<span>EWFORD</span>,</span> <i>and others</i>.</div>

<div class="sd-schg"><i>Enter at the other doore, the Duke of</i> <span class="smcaps">Y<span>ORKE</span>,</span> <i>and the Marquesse of</i>
<span class="smcaps">S<span>UFFOLKE</span>,</span> <i>and Queene</i>
<span class="smcaps">M<span>ARGARET</span>,</span> <i>and the Earle
of</i> <span class="smcaps">S<span>ALISBURY</span></span> <i>and</i> <span class="smcaps">W<span>ARWICKE</span>.</span></div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 As by your high imperiall Maiesties command,</div>
<div class="dverse">I had in charge at my depart for <i>France</i>,</div>
<div class="dverse">As Procurator for your excellence,</div>
<div class="dverse">To marry Princes <i>Margaret</i> for your grace,</div>
<div class="dverse"><span class="lnum">5</span>
 So in the auncient famous Citie Towres,</div>
<div class="dverse">In presence of the Kings of <i>France &amp; Cyssile</i>,</div>
<div class="dverse">The Dukes of <i>Orleance</i>, <i>Calabar</i>, <i>Brittaine</i>, and <i>Alonson</i>.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daa008" id="lnum-daa008">♦</a>
 Seuen Earles, twelue Barons, and then the reuerend Bishops,</div>
<div class="dverse">I did performe my taske and was espousde,</div>
<div class="dverse"><span class="lnum">10</span>
 And now, most humbly on my bended knees,</div>
<div class="dverse">In sight of England and her royall Peeres,</div>
<div class="dverse">Deliuer vp my title in the Queene,</div>
<div class="dverse">Vnto your gratious excellence, that are the substance</div>
<div class="dverse">Of that great shadow I did represent:</div>
<div class="dverse"><span class="lnum">15</span>
 The happiest gift that euer Marquesse gaue,</div>
<div class="dverse">The fairest Queene that euer King possest.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 <i>Suffolke</i> arise.</div>
<div class="dverse">Welcome Queene <i>Margaret</i> to English <i>Henries</i> Court,</div>
<div class="dverse">The greatest shew of kindnesse yet we can bestow,</div>
<div class="dverse">Is this kinde kisse: Oh gracious God of heauen,</div>
<div class="dverse">Lend me a heart repleat with thankfulnesse,</div>
<div class="dverse">For in this beautious face thou hast bestowde</div>
<div class="dverse">A world of pleasures to my perplexed soule.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 Th’ excessiue loue I beare vnto your grace,</div>
<div class="dverse"><span class="lnum">25</span>
 Forbids me to be lauish of my tongue,</div>
<div class="dverse">Least I should speake more then beseemes a woman:</div>
<div class="dverse">Let this suffice, my blisse is in your liking,</div>
<div class="dverse">And nothing can make poore <i>Margaret</i> miserable,</div>
<div class="dverse">Vnlesse the frowne of mightie Englands King.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daa030" id="lnum-daa030">30</a>
 <span class="sd-cn">Kin.</span>
  Her lookes did wound, but now her speech doth pierce,</div>
<div class="dverse">Louely Queene <i>Margaret</i> sit down by my side:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daa032" id="lnum-daa032">♦</a>
 And vnckle <i>Gloster</i>, and you Lordly Peeres,</div>
<div class="dverse">With one voice welcome my beloued Queene.</div>

<div class="dverse1"><span class="sd-cn">All.</span>
 Long liue Queene <i>Margaret</i>, Englands happinesse.</div>

<div class="dverse1"><span class="lnum">35</span>
 <span class="sd-cn">Queene.</span>
 We thanke you all.
 <span class="sd-verseend">Sound Trumpets.</span></div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 My Lord Protector, so it please your grace,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daa037" id="lnum-daa037">♦</a>
 Here are the Articles confirmde of peace,</div>
<div class="dverse">Betweene our Soueraigne and the French King <i>Charles</i>,</div>
<div class="dverse">Till terme of eighteene months be full expirde.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-daa040" id="lnum-daa040">40</a>
 <span class="sd-cn">Humphrey.</span>
<i>Imprimis</i>, It is agreed betweene the French King <a class="lnum pginternal" href="#lnote-daa041" id="lnum-daa041">♦</a>
<i>Charles</i>, and <i>William de la Poule</i>, Marquesse of <i>Suffolke</i>, Embassador for <i>Henry</i> King of England, that the said <i>Henry</i>
shal wed and espouse the Ladie <i>Margaret</i>, daughter to <i>Raynard</i> King of <i>Naples</i>, <i>Cyssels</i>, and <i>Ierusalem</i>, and crowne her Queene of
<a class="lnum pginternal" href="#lnote-daa045" id="lnum-daa045">45</a>
England, ere the 30. of the next month.</div>

<div class="dprose"><a class="lnum pginternal" href="#lnote-daa046" id="lnum-daa046">♦</a>
<i>Item.</i>
It is further agreed betweene them, that the Dutches of <i>Anioy</i>
and of <i>Maine</i>, shall be released and deliuered ouer to the King <a class="lnum pginternal" href="#lnote-daa048" id="lnum-daa048">♦</a>
her fa. <span class="sd-proseend">Duke <i>Humphrey</i> lets it fall.</span>
</div>

<div class="dverse1"><span class="sd-cn">Kin.</span>
 How now vnkle, whats the matter that you stay so sodenly.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daa050" id="lnum-daa050">50</a>
 <span class="sd-cn">Humph.</span>
  Pardon my Lord, a sodain qualme came ouer my hart,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daa051" id="lnum-daa051">♦</a>
 Which dimmes mine eyes that I can reade no more.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daa052" id="lnum-daa052">♦</a>
 Vnckle of <i>Winchester</i>, I pray you reade on.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-daa053" id="lnum-daa053">♦</a>
<span class="sd-cn">Cardinall</span>.
<i>Item</i>, It is further agreed betweene them, that the <a class="lnum pginternal" href="#lnote-daa054" id="lnum-daa054">♦</a>
Duches of <i>Anioy</i> and of <i>Mayne</i>, shall be released and deliuered <span class="lnum">55</span>
ouer to the King her father, &amp; she sent ouer of the King of Englands owne proper cost and charges without dowry.</div>

<div class="dprose1"><span class="sd-cn">King.</span>
They please vs well, Lord Marquesse kneele downe, We here create thee first Duke of <i>Suffolke</i>, &amp; girt thee with the sword. Cosin of Yorke, We here discharge your grace from being <span class="lnum">60</span>
Regent in the parts of <i>France</i>, till terme of 18. months be full expirde.</div>

<div class="dverse">Thankes vnckle <span class="sd-inline"><i>Winchester</i>, <i>Gloster</i>, <i>Yorke</i>, and <i>Buckingham</i>, <i>Somerset</i>, <i>Salsbury</i>, and <i>Warwicke</i>.</span></div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daa063" id="lnum-daa063">♦</a>
 We thanke you all for this great fauour done,</div>
<div class="dverse">In entertainment to my Princely Queene,</div>
<div class="dverse"><span class="lnum">65</span>
 Come let vs in, and with all speed prouide</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daa066" id="lnum-daa066">♦</a>
 To see her Coronation be performde.
 <span class="sd-verseend"><i>Exet</i> King, Queene, and Suffolke,
 and Duke Humphrey staies all the rest.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daa067" id="lnum-daa067">♦</a>
 <span class="sd-cn">Humphrey.</span>
 Braue Peeres of England, Pillars of the state,</div>
<div class="dverse">To you Duke <i>Humphrey</i> must vnfold his griefe,</div>
<div class="dverse">What did my brother <i>Henry</i> toyle himselfe,</div>
<div class="dverse"><span class="lnum">70</span> And waste his subjects for to conquere <i>France</i>?</div>
<div class="dverse">And did my brother <i>Bedford</i> spend his time</div>
<div class="dverse">To keepe in awe that stout vnruly Realme?</div>
<div class="dverse">And haue not I and mine vnckle <i>Bewford</i> here,</div>
<div class="dverse">Done all we could to keepe that land in peace?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daa075" id="lnum-daa075">75</a>
 And is all our labours then spent in vaine,</div>
<div class="dverse">For Suffolke he, the new made Duke that rules the roast,</div>
<div class="dverse">Hath giuen away for our King <i>Henries</i> Queene,</div>
<div class="dverse">The Dutches of <i>Anioy</i> and <i>Mayne</i> vnto her father.</div>
<div class="dverse">Ah Lords, fatall is this marriage canselling our states,</div>
<div class="dverse"><span class="lnum">80</span> Reuersing Monuments of conquered <i>France</i>,</div>
<div class="dverse">Vndoing all, as none had nere bene done.</div>

<div class="dverse1"><span class="sd-cn">Card.</span>
 Why how now cosin <i>Gloster</i>, what needs this?</div>
<div class="dverse">As if our King were bound vnto your will,</div>
<div class="dverse">And might not do his will without your leaue,</div>
<div class="dverse"><span class="lnum">85</span>
 Proud Protector, enuy in thine eyes I see,</div>
<div class="dverse">The big swolne venome of thy hatefull heart,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daa087" id="lnum-daa087">♦</a>
 That dares presume gainst that thy Soueraigne likes.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daa088" id="lnum-daa088">♦</a>
 <span class="sd-cn">Humphr.</span>
  Nay my Lord tis not my words that troubles you,</div>
<div class="dverse">But my presence, proud Prelate as thou art:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daa090" id="lnum-daa090">90</a>
 But ile begone, and giue thee leaue to speake.</div>
<div class="dverse">Farewell my Lords, and say when I am gone,</div>
<div class="dverse">I prophesied <i>France</i> would be lost ere long. <span class="sd-verseend"><i>Exet</i> Duke <i>Humphrey</i>.</span></div>

<div class="dverse1"><span class="sd-cn">Card.</span>
 There goes our Protector in a rage,</div>
<div class="dverse">My Lords you know he is my great enemy,</div>
<div class="dverse"><span class="lnum">95</span>
 And though he be Protector of the land,</div>
<div class="dverse">And thereby couers his deceitfull thoughts,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daa097" id="lnum-daa097">♦</a>
 For well you see, if he but walke the streets,</div>
<div class="dverse">The common people swarme about him straight,</div>
<div class="dverse">Crying Iesus blesse your royall exellence,</div>
<div class="dverse"><span class="lnum">100</span>
 With God preserue the good Duke <i>Humphrey</i>.</div>
<div class="dverse">And many things besides that are not knowne,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daa112" id="lnum-daa112">♦</a>
 Which time will bring to light in smooth Duke <i>Humphrey</i>.</div>
<div class="dverse">But I will after him, and if I can</div>
<div class="dverse">Ile laie a plot to heaue him from his seate. <span class="sd-verseend"><i>Exet</i> Cardinall.</span></div>

<div class="dverse1"><span class="lnum">105</span>
 <span class="sd-cn">Buck.</span>
  But let vs watch this haughtie Cardinall,</div>
<div class="dverse">Cosen of <i>Somerset</i> be rulde by me,</div>
<div class="dverse">Weele watch Duke <i>Humphrey</i> and the Cardinall too,</div>
<div class="dverse">And put them from the marke they faine would hit.</div>

<div class="dverse1"><span class="sd-cn">Somerset.</span>
 Thanks cosin <i>Buckingham</i>, ioyne thou with me,</div>
<div class="dverse"><span class="lnum">110</span>
 And both of vs with the Duke of <i>Suffolke</i>,</div>
<div class="dverse">Weele quickly heaue Duke <i>Humphrey</i> from his seate.</div>

<div class="dverse1"><span class="sd-cn">Buck.</span>
 Content, Come then let vs about it straight,</div>
<div class="dverse">For either thou or I will be Protector. <span class="sd-verseend"><i>Exet Buckingham and Somerset.</i></span></div>

<div class="dverse1"><span class="sd-cn">Salsb.</span>
 Pride went before, Ambition follows after.</div>
<div class="dverse"><span class="lnum">115</span>
 Whilst these do seeke their owne preferments thus,</div>
<div class="dverse">My Lords let vs seeke for our Countries good,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daa117" id="lnum-daa117">♦</a>
 Oft haue I seene this haughtie Cardinall</div>
<div class="dverse">Sweare, and forsweare himselfe, and braue it out,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daa119" id="lnum-daa119">♦</a>
 More like a Ruffin then a man of Church.</div>
<div class="dverse"><span class="lnum">120</span>
 Cosin <i>Yorke</i>, the victories thou hast wonne,</div>
<div class="dverse">In <i>Ireland</i>, <i>Normandie</i>, and in <i>France,</i></div>
<div class="dverse">Hath wonne thee immortall praise in England.</div>
<div class="dverse">And thou braue <i>Warwicke</i>, my thrice valiant sonne,</div>
<div class="dverse">Thy simple plainnesse and thy house-keeping,</div>
<div class="dverse"><span class="lnum">125</span>
 Hath wonne thee credit amongst the common sort,</div>
<div class="dverse">The reuerence of mine age, and <i>Neuels</i> name,</div>
<div class="dverse">Is of no little force if I command,</div>
<div class="dverse">Then let vs ioyne all three in one for this,</div>
<div class="dverse">That good Duke <i>Humphrey</i> may his state possesse,</div>
<div class="dverse">But wherefore weepes <i>Warwicke</i> my noble sonne.</div>

<div class="dverse1"><span class="sd-cn">Warw.</span>
 For griefe that all is lost that <i>Warwick</i> won.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daa132" id="lnum-daa132">♦</a>
 Sonnes. <i>Anioy</i> and <i>Maine,</i> both giuen away at once,</div>
<div class="dverse">Why <i>Warwick</i> did win them, &amp; must that then which we wonne with our swords, be giuen away with wordes.</div>

<div class="dprose1"><span class="lnum">135</span>
 <span class="sd-cn">Yorke.</span>
 As I haue read, our Kinges of England were woont to haue large dowries with their wiues, but our King <i>Henry</i> giues away his owne.</div>

<div class="dverse1"><span class="sd-cn">Sals.</span>
 Come sonnes away and looke vnto the maine.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Vnto the <i>Maine</i>, Oh father <i>Maine</i> is lost,</div>
<div class="dverse"><span class="lnum">140</span>
 Which <i>Warwicke</i> by maine force did win from <i>France</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daa141" id="lnum-daa141">♦</a>
 Maine chance father you meant, but I meant <i>Maine</i>,</div>
<div class="dverse">Which I will win from <i>France</i>, or else be slaine.
 <span class="sd-verseend"><i>Exet Salsbury</i> and <i>Warwicke</i>.</span></div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 <i>Anioy</i> and <i>Maine</i>, both giuen vnto the French,</div>
<div class="dverse">Cold newes for me, for I had hope of <i>France</i>,</div>
<div class="dverse"><span class="lnum">145</span>
 Euen as I haue of fertill England.</div>
<div class="dverse">A day will come when <i>Yorke</i> shall claime his owne,</div>
<div class="dverse">And therefore I will take the <i>Neuels</i> parts,</div>
<div class="dverse">And make a show of loue to proud Duke <i>Humphrey</i>:</div>
<div class="dverse">And when I spie aduantage, claime the Crowne,</div>
<div class="dverse"><span class="lnum">150</span>
 For thats the golden marke I seeke to hit:</div>
<div class="dverse">Nor shall proud <i>Lancaster</i> vsurpe my right,</div>
<div class="dverse">Nor hold the scepter in his childish fist,</div>
<div class="dverse">Nor weare the Diademe vpon his head,</div>
<div class="dverse">Whose church-like humours fits not for a Crowne:</div>
<div class="dverse"><span class="lnum">155</span>
 Then <i>Yorke</i> be still a while till time do serue,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daa156" id="lnum-daa156">♦</a>
 Watch thou, and wake when others be a sleepe,</div>
<div class="dverse">To prie into the secrets of the state,</div>
<div class="dverse">Till <i>Henry</i> surfeiting in ioyes of loue,</div>
<div class="dverse">With his new bride, and Englands dear bought queene,</div>
<div class="dverse"><span class="lnum">160</span>
 And <i>Humphrey</i> with the Peeres be falne at iarres,</div>
<div class="dverse">Then will I raise aloft the milke-white Rose,</div>
<div class="dverse">With whose sweete smell the aire shall be perfumde,</div>
<div class="dverse">And in my Standard beare the Armes of <i>Yorke</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daa164" id="lnum-daa164">♦</a>
 To graffle with the House of <i>Lancaster</i>:</div>
<div class="dverse"><span class="lnum">165</span>
 And force perforce, ile make him yeeld the Crowne,</div>
<div class="dverse">Whose bookish rule hath puld faire England downe. <span class="sd-verseend"><i>Exet Yorke.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> II.
<span class="dnavigatenf">dab</span></h3>

Enter Duke <i>Humphrey</i>, and Dame <i>Ellanor</i>, <i>Cobham</i> his wife.</div>

<div class="dverse1"><span class="sd-cn">Elnor.</span>
 Why droopes my Lord like ouer ripened corne,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dab002" id="lnum-dab002">♦</a>
 Hanging the head at <i>Cearies</i> plentious loade,</div>
<div class="dverse">What seest thou Duke <i>Humphrey</i> King <i>Henries</i> Crowne?</div>
<div class="dverse">Reach at it, and if thine arme be too short,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dab005" id="lnum-dab005">5</a>
 Mine shall lengthen it. Art not thou a Prince,</div>
<div class="dverse">Vnckle to the King, and his Protector?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dab007" id="lnum-dab007">♦</a>
 Then what shouldst thou lacke that might content thy minde.</div>

<div class="dverse1"><span class="sd-cn">Humph.</span>
 My louely <i>Nell</i>, far be it from my heart,</div>
<div class="dverse">To thinke of Treasons gainst my soueraigne Lord,</div>
<div class="dverse"><span class="lnum">10</span>
 But I was troubled with a dreame to night,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dab011" id="lnum-dab011">♦</a>
 And God I pray, it do betide no ill.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dab012" id="lnum-dab012">♦</a>
 <span class="sd-cn">Elnor.</span>
 What drempt my Lord. Good <i>Humphrey</i> tell it me,</div>
<div class="dverse">And ile interpret it, and when thats done,</div>
<div class="dverse">Ile tell thee then, what I did dreame to night.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dab015" id="lnum-dab015">15</a>
 <span class="sd-cn">Humphrey.</span>
  This night when I was laid in bed, I dreampt that</div>
<div class="dverse">This my staffe mine Office badge in Court,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dab017" id="lnum-dab017">♦</a>
 Was broke in two, and on the ends were plac’d,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dab018" id="lnum-dab018">♦</a>
 The heads of the Cardinall of <i>Winchester</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dab019" id="lnum-dab019">♦</a>
 And <i>William de la Poule</i> first Duke of <i>Suffolke</i>.</div>

<div class="dverse1"><span class="lnum">20</span>
 <span class="sd-cn">Elnor.</span>
  Tush my Lord, this signifies nought but this,</div>
<div class="dverse">That he that breakes a sticke of <i>Glosters</i> groue,</div>
<div class="dverse">Shall for th’ offence, make forfeit of his head.</div>
<div class="dverse">But now my Lord, Ile tell you what I dreampt,</div>
<div class="dverse">Me thought I was in the Cathedrall Church</div>
<div class="dverse"><span class="lnum">25</span>
 At Westminster, and seated in the chaire</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dab026" id="lnum-dab026">♦</a>
 Where Kings and Queenes are crownde, and at my feete</div>
<div class="dverse"><i>Henry</i> and <i>Margaret</i> with a Crowne of gold</div>
<div class="dverse">Stood readie to set it on my Princely head.</div>

<div class="dverse1"><span class="sd-cn">Humphrey.</span>
 Fie <i>Nell</i>. Ambitious woman as thou art,</div>
<div class="dverse"><span class="lnum">30</span>
 Art thou not second woman in this land,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dab031" id="lnum-dab031">♦</a>
 And the Protectors wife belou’d of him,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dab032" id="lnum-dab032">♦</a>
 And wilt thou still be hammering treason thus,</div>
<div class="dverse">Away I say, and let me heare no more.</div>

<div class="dverse1"><span class="sd-cn">Elnor.</span>
 How now my Lord. What angry with your <i>Nell</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dab035" id="lnum-dab035">35</a>
 For telling but her dreame. The next I haue</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dab036" id="lnum-dab036">♦</a>
 Ile keepe to my selfe, and not be rated thus.</div>

<div class="dverse1"><span class="sd-cn">Humphrey.</span>
 Nay <i>Nell</i>, Ile giue no credit to a dreame,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dab038" id="lnum-dab038">♦</a>
 But I would haue thee to thinke on no such things.</div>

<div class="sd-entry">Enters a Messenger.</div>

<div class="dprose1"><span class="sd-cn">Messenger.</span>
 And it please your grace, the King and Queene to <a class="lnum pginternal" href="#lnote-dab040" id="lnum-dab040">40</a>
 morrow morning will ride a hawking to Saint Albones, and craues your company along with them.</div>

<div class="dverse1"><span class="sd-cn">Humphrey.</span>
 With all my heart, I will attend his grace:</div>
<div class="dverse">Come <i>Nell</i>, thou wilt go with vs vs I am sure. <a class="lnum pginternal" href="#lnote-dab043" id="lnum-dab043">♦</a>
<span class="sd-verseend"><i>Exet Humphrey.</i></span></div>

<div class="dverse1"><span class="sd-cn">Elnor.</span>
 Ile come after you, for I cannot go before,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dab045" id="lnum-dab045">45</a>
 But ere it be long, Ile go before them all,</div>
<div class="dverse">Despight of all that seeke to crosse me thus,</div>
<div class="dverse">Who is within there?</div>

<div class="sd-entry">Enter sir <i>Iohn Hum</i>.</div>

<div class="dverse">What sir <i>Iohn Hum</i>, what newes with you?</div>

<div class="dverse1"><span class="sd-cn">Sir Iohn.</span>
 Iesus preserue your Maiestie.</div>

<div class="dverse1"><span class="lnum">50</span>
 <span class="sd-cn">Elnor.</span>
  My Maiestie. Why man I am but grace.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dab051" id="lnum-dab051">♦</a>
 <span class="sd-cn">Ser Iohn.</span>
 I, but by the grace of God &amp; <i>Hums</i> aduise,</div>
<div class="dverse">Your graces state shall be aduanst ere long.</div>

<div class="dprose1"><span class="sd-cn">Elnor.</span>
 What hast thou conferd with <i>Margery Iordaine</i>, the <a class="lnum pginternal" href="#lnote-dab054" id="lnum-dab054">♦</a>
 cunning Witch of <i>Ely</i>, with <i>Roger Bullingbrooke</i> and the <a class="lnum pginternal" href="#lnote-dab055" id="lnum-dab055">55</a>
 rest, and will they vndertake to do me good?</div>

<div class="dprose1"><span class="sd-cn">Sir Iohn.</span>
 I haue Madame, and they haue promised me to raise a <a class="lnum pginternal" href="#lnote-dab057" id="lnum-dab057">♦</a>
 Spirite from depth of vnder grounde, that shall tell your grace all questions you demaund.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dab059" id="lnum-dab059">♦</a>
 <span class="sd-cn">Elnor.</span>
 Thanks good sir <i>Iohn</i>. Some two daies hence I gesse</div>
<div class="dverse"><span class="lnum">60</span>
 Will fit our time, then see that they be here:</div>
<div class="dverse">For now the King is ryding to Saint Albones,</div>
<div class="dverse">And all the Dukes and Earles along with him,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dab063" id="lnum-dab063">♦</a>
 When they be gone, then safely they may come,</div>
<div class="dverse">And on the backside of my Orchard heere,</div>
<div class="dverse"><span class="lnum">65</span>
 There cast their Spelles in silence of the night,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dab066" id="lnum-dab066">♦</a>
 And so resolue vs of the thing we wish,</div>
<div class="dverse">Till when, drinke that for my sake, And so farwell. <span class="sd-verseend"><i>Exet Elnor.</i></span></div>

<div class="dverse1"><span class="sd-cn">Sir Iohn.</span>
 Now sir <i>Iohn Hum</i>, No words but mum.</div>
<div class="dverse">Seale vp your lips, for you must silent be,</div>
<div class="dverse"><span class="lnum">70</span>
 These gifts ere long will make me mightie rich.</div>
<div class="dverse">The Duches she thinks now that all is well,</div>
<div class="dverse">But I haue gold comes from another place,</div>
<div class="dverse">From one that hyred me to set her on,</div>
<div class="dverse">To plot these Treasons gainst the King and Peeres,</div>
<div class="dverse"><span class="lnum">75</span>
 And that is the mightie Duke of <i>Suffolke</i>.</div>
<div class="dverse">For he it is, but I must not say so,</div>
<div class="dverse">That by my meanes must worke the Duches fall,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dab078" id="lnum-dab078">♦</a>
 Who now by Cuniurations thinkes to rise.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dab079" id="lnum-dab079">♦</a>
 But whist sir <i>Iohn,</i> no more of that I trow,</div>
<div class="dverse"><span class="lnum">80</span>
 For feare you lose your head before you goe.
 <span class="sd-verseend"><i>Exet.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> III.
 <span class="dnavigatenf">dac</span></h3>

Enter two Petitioners, and <i>Peter</i> the Armourers man.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac001" id="lnum-dac001">♦</a>
 <span class="sd-cn">1. Peti.</span>
  Come sirs let vs linger here abouts a while,</div>
<div class="dverse">Vntil my Lord Protector come this way,</div>
<div class="dverse">That we may show his grace our seuerall causes.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac004" id="lnum-dac004">♦</a>
 <span class="sd-cn">2. Peti.</span>
 I pray God saue the good Duke <i>Humphries</i> life,</div>
<div class="dverse"><span class="lnum">5</span>
 For but for him a many were vndone,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac006" id="lnum-dac006">♦</a>
 That cannot get no succour in the Court,</div>
<div class="dverse">But see where he comes with the Oueene.</div>

<div class="sd-entry">Enter the Duke of <i>Suffolke</i> with the Queene, and they take him for Duke <i>Humphrey</i>, and giues him their writings.</div>

<div class="dverse1"><span class="sd-cn">1. Peti.</span>
 Oh we are vndone, this is the Duke of <i>Suffolke</i>.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 Now good-fellowes, whom would you speak withall?</div>

<div class="dverse1"><span class="lnum">10</span>
 <span class="sd-cn">2. Peti.</span>
  If it please your Maiestie, with my Lord Protectors</div>
<div class="dverse">Grace.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac012" id="lnum-dac012">♦</a>
 <span class="sd-cn">Queene.</span>
  Are your sutes to his grace. Let vs see them first,</div>
<div class="dverse">Looke on them my Lord of <i>Suffolke</i>.</div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 A complaint against the Cardinals man,</div>
<div class="dverse"><span class="lnum">15</span>
 What hath he done?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac016" id="lnum-dac016">♦</a>
 <span class="sd-cn">2. Peti.</span>
  Marry my Lord, he hath stole away my wife,</div>
<div class="dverse">And th’ are gone togither, and I know not where to finde them.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac018" id="lnum-dac018">♦</a>
 <span class="sd-cn">Suffolke.</span>
  Hath he stole thy wife, thats some iniury indeed.</div>
<div class="dverse">But what say you?</div>

<div class="dprose1"><span class="lnum">20</span>
 <span class="sd-cn">Peter Thump.</span>
 Marry sir I come to tel you that my maister said, <a class="lnum pginternal" href="#lnote-dac021" id="lnum-dac021">♦</a>
 that the Duke of <span class="nowrap"><i>Yor</i>k<i>e</i></span>
 was true heire vnto the Crowne, and that the King was an vsurer.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 An vsurper thou wouldst say.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac024" id="lnum-dac024">♦</a>
 <span class="sd-cn">Peter.</span>
  I forsooth an vsurper.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Queene.</span>
  Didst thou say the King was an vsurper?</div>

<div class="dprose1"><span class="sd-cn">Peter.</span>
 No forsooth, I saide my maister saide so, th’ other day, when we were scowring the Duke of <i>Yorks</i> Armour in our garret.</div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 I marry this is something like,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac030" id="lnum-dac030">30</a>
 Whose within there?</div>

<div class="sd-entry">Enter one or two.</div>

<div class="dverse"><a class="lnum pginternal" href="#lnote-dac031" id="lnum-dac031">♦</a>
 Sirra take in this fellow and keepe him close,</div>
<div class="dverse">And send out a Purseuant for his maister straight,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac033" id="lnum-dac033">♦</a>
 Weele here more of this before the King.
 <span class="sd-verseend"><i>Exet</i> with the Armourers man.</span></div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac034" id="lnum-dac034">♦</a>
 Now sir what yours? Let me see it,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac035" id="lnum-dac035">35</a>
 Whats here?</div>
<div class="dverse">A complaint against the Duke of <i>Suffolke</i>
for enclosing the commons of long Melford.</div>

<div class="dverse"><a class="lnum pginternal" href="#lnote-dac038" id="lnum-dac038">♦</a>
 How now sir knaue.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dac039" id="lnum-dac039">♦</a>
 <span class="sd-cn">1. Peti.</span>
 I beseech your grace to pardon me, me, I am but a <span class="lnum">40</span>
 Messenger for the whole town-ship.
 <span class="sd-proseend">He teares the papers.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac041" id="lnum-dac041">♦</a>
 <span class="sd-cn">Suffolke.</span>
 So now show your petitions to Duke <i>Humphrey</i>.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac042" id="lnum-dac042">♦</a>
 Villaines get you gone and come not neare the Court,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac043" id="lnum-dac043">♦</a>
 Dare these pesants write against me thus.
 <span class="sd-verseend"><i>Exet</i> Petitioners.</span></div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 My Lord of <i>Suffolke</i>, you may see by this,</div>
<div class="dverse"><span class="lnum">45</span>
 The Commons loues vnto that haughtie Duke,</div>
<div class="dverse">That seekes to him more then to King <i>Henry</i>:</div>
<div class="dverse">Whose eyes are alwaies poring on his booke,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac048" id="lnum-dac048">♦</a>
 And nere regards the honour of his name,</div>
<div class="dverse">But still must be protected like a childe,</div>
<div class="dverse"><span class="lnum">50</span>
 And gouerned by that ambitious Duke,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac051" id="lnum-dac051">♦</a>
 That scarse will moue his cap nor speake to vs,</div>
<div class="dverse">And his proud wife, high minded <i>Elanor</i>,</div>
<div class="dverse">That ruffles it with such a troupe of Ladies,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac054" id="lnum-dac054">♦</a>
 As strangers in the Court takes her for the Queene.</div>
<div class="dverse"><span class="lnum">55</span>
 The other day she vanted to her maides,</div>
<div class="dverse">That the very traine of her worst gowne,</div>
<div class="dverse">Was worth more wealth then all my fathers lands,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac058" id="lnum-dac058">♦</a>
 Can any griefe of minde be like to this.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac059" id="lnum-dac059">♦</a>
 I tell thee <i>Poull</i>, when thou didst runne at Tilt,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac060" id="lnum-dac060">60</a>
 And stolst away our Ladaies hearts in <i>France</i>,</div>
<div class="dverse">I thought King <i>Henry</i> had bene like to thee,</div>
<div class="dverse">Or else thou hadst not brought me out of <i>France</i>.</div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 Madame content your selfe a litle while,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac064" id="lnum-dac064">♦</a>
 As I was cause of your comming to England,</div>
<div class="dverse"><span class="lnum">65</span>
 So will I in England worke your full content:</div>
<div class="dverse">And as for proud Duke <i>Humphrey</i> and his wife,</div>
<div class="dverse">I haue set lime-twigs that will intangle them,</div>
<div class="dverse">As that your grace ere long shall vnderstand.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac069" id="lnum-dac069">♦</a>
 But staie Madame, here comes the King.</div>

<div class="sd-entry">Enter King <i>Henry</i>, and the Duke of <i>Yorke</i> and the Duke of <i>Somerset</i> on both sides of the King, whispering with him, and enter Duke <i>Humphrey</i>, Dame <i>Elnor</i>, the Duke of <i>Buckingham</i>, the Earle of <i>Salsbury</i>, the Earle of <i>Warwicke</i>, and the Cardinall of <i>Winchester</i>.</div>

<div class="dprose1"><span class="lnum">70</span>
 <span class="sd-cn">King.</span>
 My Lords I care not who be Regent in <i>France</i>, or <i>York</i>, <a class="lnum pginternal" href="#lnote-dac071" id="lnum-dac071">♦</a>
 or Somerset, alls wonne to me.</div>

<div class="dverse1"><span class="sd-cn">Yorke</span>
 My Lord, if <i>Yorke</i> haue ill demeande himselfe,</div>
<div class="dverse">Let <i>Somerset</i> enioy his place and go to <i>France</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac074" id="lnum-dac074">♦</a>
 <span class="sd-cn">Somerset.</span>
  Then whom your grace thinke worthie, let him go,</div>
<div class="dverse"><span class="lnum">75</span>
 And there be made the Regent ouer the French.</div>

<div class="dverse1"><span class="sd-cn">Warwicke.</span>
 Whom soeuer you account worthie,</div>
<div class="dverse"><i>Yorke</i> is the worthiest.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac078" id="lnum-dac078">♦</a>
 <span class="sd-cn">Cardinall.</span>
 Pease <i>Warwicke</i>. Giue thy betters leaue to speake.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac079" id="lnum-dac079">♦</a>
 <span class="sd-cn">War.</span>
  The Cardinals not my better in the field.</div>

<div class="dverse1"><span class="lnum">80</span>
 <span class="sd-cn">Buc.</span>
  All in this place are thy betters farre.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac081" id="lnum-dac081">♦</a>
 <span class="sd-cn">War.</span>
 And <i>Warwicke</i> may liue to be the best of all.</div>

<div class="dprose1"><span class="sd-cn">Queene.</span>
My Lord in mine opinion, it were best that <i>Somerset</i> were Regent ouer <i>France</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac084" id="lnum-dac084">♦</a>
 <span class="sd-cn">Humphrey.</span>
  Madame onr King is old inough himselfe,</div>
<div class="dverse"><span class="lnum">85</span>
 To giue his answere without your consent.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac086" id="lnum-dac086">♦</a>
 <span class="sd-cn">Queene.</span>
  If he be old inough, what needs your grace</div>
<div class="dverse">To be Protector ouer him so long.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac088" id="lnum-dac088">♦</a>
 <span class="sd-cn">Humphrey.</span>
  Madame I am but Protector ouer the land,</div>
<div class="dverse">And when it please his grace, I will resigne my charge.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac090" id="lnum-dac090">90</a>
 <span class="sd-cn">Suffolke.</span>
  Resigne it then, for since that thou wast King,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac091" id="lnum-dac091">♦</a>
 As who is King but thee. The common state</div>
<div class="dverse">Doth as we see, all wholly go to wracke,</div>
<div class="dverse">And Millions of treasure hath bene spent,</div>
<div class="dverse">And as for the Regentship of <i>France</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac095" id="lnum-dac095">95</a>
 I say <i>Somerset</i> is more worthie then <i>Yorke</i>.</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 Ile tell thee <i>Suffolke</i> why I am not worthie,</div>
<div class="dverse">Because I cannot flatter as thou canst.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 And yet the worthie deeds that <i>York</i> hath done,</div>
<div class="dverse">Should make him worthie to be honoured here.</div>

<div class="dverse1"><span class="lnum">100</span>
 <span class="sd-cn">Suffolke.</span>  Peace headstrong <i>Warwicke</i>.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Image of pride, wherefore should I peace?</div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 Because here is a man accusde of Treason,</div>
<div class="dverse">Pray God the Duke of <i>Yorke</i> do cleare himselfe.</div>
<div class="dverse">Ho, bring hither the Armourer and his man.</div>

<div class="sd-entry">Enter the Armourer and his man.</div>

<div class="dprose1"><span class="lnum">105</span>
 If it please your grace, this fellow here, hath accused his maister of high Treason, And his words were these.</div>

<div class="dprose1">That the Duke of <i>Yorke</i>
 was lawfull heire vnto the Crowne, and that your grace was an vsurper.</div>

<div class="dprose1"><span class="sd-cn">Yorke.</span>
 I beseech your grace let him haue what punishment the <span class="lnum">110</span>
 law will afford, for his villany.</div>

<div class="dprose1"><span class="sd-cn">King.</span>
 Come hether fellow, didst thou speake these words?</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dac112" id="lnum-dac112">♦</a>
 <span class="sd-cn">Armour.</span>
 Ant shall please your Maiestie, I neuer said any such
 <span id="lnum-dac113">matter,</span> God is my witnesse,
 I am falsly accused by this villain (here.</div>

<div class="dprose1"><span class="lnum">115</span>
 <span class="sd-cn">Peter.</span>
 Tis no matter for that, you did say so.</div>

<div class="dprose1"><span class="sd-cn">Yorke.</span>
 I beseech your grace, let him haue the law.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dac117" id="lnum-dac117">♦</a>
 <span class="sd-cn">Armour.</span>
 Alasse my Lord, hang me if euer I spake the words, my accuser is my prentise, &amp; when I did correct him for his fault the other day, he did vow upon his knees that he would <span class="lnum">120</span>
 be euen with me, I haue good witnesse of this, and therefore <a class="lnum pginternal" href="#lnote-dac121" id="lnum-dac121">♦</a>
 I beseech your Maiestie do not cast away an honest man for a villaines accusation.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Vnckle <i>Gloster</i>, what do you thinke of this?</div>

<div class="dverse1"><span class="sd-cn">Humphrey.</span>
 The law my Lord is this by case, it rests suspitious,</div>
<div class="dverse"><span class="lnum">125</span>
 That a day of combat be appointed,</div>
<div class="dverse">And there to trie each others right or wrong,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac127" id="lnum-dac127">♦</a>
 Which shall be on the thirtith of this month,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac128" id="lnum-dac128">♦</a>
 With <i>Eben</i> staues, and <i>Standbags</i> combatting</div>
<div class="dverse">In Smythfield, before your Royall Maiestie. <span class="sd-verseend"><i>Exet Humphrey.</i></span></div>

<div class="dverse1"><span class="lnum">130</span>
 <span class="sd-cn">Armour.</span>
  And I accept the Combat willingly.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac131" id="lnum-dac131">♦</a>
 <span class="sd-cn">Peter.</span>
  Alasse my Lord, I am not able to fight.</div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 You must either fight sirra or else be hangde:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac133" id="lnum-dac133">♦</a>
 Go take them hence againe to prison.
 <span class="sd-inline">  <i>Exet</i> with them.</span>
 <span class="sd-verseend">The Queene lets fall her gloue, and hits
 the Duches of <i>Gloster</i>, a boxe on the eare.</span></div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 Giue me my gloue. Why Minion can you not see? <span class="sd-verseend">She strikes her.</span></div>

<div class="dverse"><span class="lnum">135</span>
 I cry you mercy Madame, I did mistake,</div>
<div class="dverse"><i>I</i> did not thinke it had bene you.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac137" id="lnum-dac137">♦</a>
 <span class="sd-cn">Elnor.</span>
  Did you not proud French-woman,</div>
<div class="dverse">Could <i>I</i> come neare your daintie vissage with my nayles,</div>
<div class="dverse">Ide set my ten commandments in your face.</div>

<div class="dverse1"><span class="lnum">140</span>
 <span class="sd-cn">King.</span>
  Be patient gentle Aunt.</div>
<div class="dverse">It was against her will.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac142" id="lnum-dac142">♦</a>
 <span class="sd-cn">Elnor.</span>
  Against her will. Good King sheele dandle thee,</div>
<div class="dverse">If thou wilt alwaies thus be rulde by her.</div>
<div class="dverse">But let it rest. As sure as <i>I</i> do liue,</div>
<div class="dverse"><span class="lnum">145</span>
 She shall not strike dame <i>Elnor</i> vnreuengde.
 <span class="sd-verseend"><i>Exet Elnor.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac146" id="lnum-dac146">♦</a>
 <span class="sd-cn">King.</span>
  Beleeue me my loue, thou wart much to blame,</div>
<div class="dverse">I would not for a thousand pounds of gold,</div>
<div class="dverse">My noble vnckle had bene here in place.</div>

<div class="sd-entry">Enter Duke <i>Humphrey</i>.</div>

<div class="dverse">But see where he comes, <i>I</i> am glad he met her not.</div>
<div class="dverse"><span class="lnum">150</span>
 Vnckle <i>Gloster</i>, what answere makes your grace</div>
<div class="dverse">Concerning our Regent for the Realme of <i>France</i>,</div>
<div class="dverse">Whom thinks your grace is meetest for to send.</div>

<div class="dverse1"><span class="sd-cn">Humphrey.</span>
 My gratious Lord, then this is my resolue,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac154" id="lnum-dac154">♦</a>
 For that these words the Armourer should speake,</div>
<div class="dverse"><span class="lnum">155</span>
 Doth breed suspition on the part of <i>Yorke</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac156" id="lnum-dac156">♦</a>
 Let <i>Somerset</i> be Regent ouer the French,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac157" id="lnum-dac157">♦</a>
 Till trials made, and <i>Yorke</i> may cleare himselfe.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Then be it so my Lord of <i>Somerset</i>.</div>
<div class="dverse">We make your grace Regent ouer the French,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac160" id="lnum-dac160">160</a>
 And to defend our rights gainst forraine foes,</div>
<div class="dverse">And so do good vnto the Realme of <i>France</i>.</div>
<div class="dverse">Make hast my Lord, tis time that you were gone,</div>
<div class="dverse">The time of Truse I thinke is full expirde.</div>

<div class="dverse1"><span class="sd-cn">Somerset.</span>
 I humbly thanke your royall Maiestie,</div>
<div class="dverse">And take my leaue to poste with speed to <i>France</i>. <span class="lnum">165</span>
 <span class="sd-verseend"><i>Exet Somerset.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dac166" id="lnum-dac166">♦</a>
 <span class="sd-cn">King.</span>
 Come vnckle <i>Gloster</i>, now lets haue our horse,</div>
<div class="dverse">For we will to Saint Albones presently,</div>
<div class="dverse">Madame your Hawke they say, is swift of flight,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dac169" id="lnum-dac169">♦</a>
 And we will trie how she will flie to day.
 <span class="sd-verseend"><i>Exet omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span>
IV. <span class="dnavigatenf">dad</span></h3>

Enter <i>Elnor</i>, with sir <i>Iohn Hum</i>, <i>Koger Bullenbrooke</i> a Coniurer,
and <i>Margery Iourdaine</i> a Witch.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dad001" id="lnum-dad001">♦</a>
 <span class="sd-cn">Elnor.</span>
 Here sir <i>Iohn</i>, take this scrole of paper here,</div>
<div class="dverse">Wherein is writ the questions you shall aske,</div>
<div class="dverse">And I will stand vpon this Tower here,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dad004" id="lnum-dad004">♦</a>
 And here the spirit what it saies to you,</div>
<div class="dverse">And to my questions, write the answeres downe. <span class="lnum">5</span>
 <span class="sd-verseend">She goes vp to the Tower.</span></div>

<div class="dverse1"><span class="sd-cn">Sir Iohn.</span>
 Now sirs begin and cast your spels about,</div>
<div class="dverse">And charme the fiendes for to obey your wils,</div>
<div class="dverse">And tell Dame <i>Elnor</i> of the thing she askes.</div>

<div class="dverse1"><span class="sd-cn">Witch.</span>
 Then <i>Roger Bullinbrooke</i> about thy taske,</div>
<div class="dverse"><span class="lnum">10</span>
 And frame a Cirkle here vpon the earth,</div>
<div class="dverse">Whilst I thereon all prostrate on my face,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dad012" id="lnum-dad012">♦</a>
 Do talke and whisper with the diuels be low,</div>
<div class="dverse">And coniure them for to obey my will. <span class="sd-verseend">She lies downe vpon her face.</span>
 <span class="sd-verseend"><i>Bullenbrooke</i> makes a Cirkle.</span></div>

<div class="dverse1"><span class="sd-cn">Bullen.</span>
 Darke Night, dread Night, the silence of the Night.</div>
<div class="dverse"><span class="lnum">15</span>
 Wherein the Furies maske in hellish troupes,</div>
<div class="dverse">Send vp I charge you from <i>Sosetus</i> lake,</div>
<div class="dverse">The spirit <i>Askalon</i> to come to me,</div>
<div class="dverse">To pierce the bowels of this Centricke earth,</div>
<div class="dverse">And hither come in twinkling of an eye,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dad020" id="lnum-dad020">20</a>
 <i>Askalon, Assenda, Assenda</i>.
 <span class="sd-verseend">It thunders and lightens, and then the spirit riseth vp.</span></div>

<div class="dverse1"><span class="sd-cn">Spirit.</span>
 Now <i>Bullenbrooke</i> what wouldst thou haue me do?</div>

<div class="dverse1"><span class="sd-cn">Bullen.</span>
 First of the King, what shall become of him?</div>

<div class="dverse1"><span class="sd-cn">Spirit.</span>
 The Duke yet liues that <i>Henry</i> shall depose,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dad024" id="lnum-dad024">♦</a>
 But him out liue, and dye a violent death.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dad025" id="lnum-dad025">25</a>
 <span class="sd-cn">Bullen.</span>
 What fate awayt the Duke of <i>Suffolke</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dad026" id="lnum-dad026">♦</a>
 <span class="sd-cn">Spirit.</span>
  By water shall he die and take his ende.</div>

<div class="dverse1"><span class="sd-cn">Bullen.</span>
 What shall betide the Duke of <i>Somerset</i>?</div>

<div class="dprose1"><span class="sd-cn">Spirit.</span>
 Let him shun Castles, safer shall he be vpon the sandie <a class="lnum pginternal" href="#lnote-dad029" id="lnum-dad029">♦</a>
 plaines, then where Castles mounted stand.</div>
<div class="dverse"><span class="lnum">30</span>
 Now question me no more, for I must hence againe.
 <span class="sd-verseend">He sinkes downe againe.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dad031" id="lnum-dad031">♦</a>
 <span class="sd-cn">Bullen.</span>
  Then downe I say, vnto the damned poule.</div>
<div class="dverse">Where Pluto in his firie Waggon sits.</div>
<div class="dverse">Ryding amidst the singde and parched smoakes,</div>
<div class="dverse">The Rode of <i>Dytas</i> by the Riuer Stykes,</div>
<div class="dverse"><span class="lnum">35</span>
 There howle and burne for euer in those flames,</div>
<div class="dverse">Rise <i>Iordaine</i> rise, and staie thy charming Spels.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dad037" id="lnum-dad037">♦</a>
 Sonnes, we are betraide.</div>

<div class="sd-entry">Enter the Duke of <i>Yorke</i>, and the Duke of <i>Buckingham</i>, and others.</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 Come sirs, laie hands on them, and bind them sure,</div>
<div class="dverse">This time was well watcht. What Madame are you there?</div>
<div class="dverse"><span class="lnum">40</span>
 This will be great credit for your husband,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dad041" id="lnum-dad041">♦</a>
 That your are plotting Treasons thus with Cuniurers,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dad042" id="lnum-dad042">♦</a>
 The King shall haue notice of this thing.
 <span class="sd-verseend"><i>Exet Elnor</i> aboue.</span></div>

<div class="dverse1"><span class="sd-cn">Buc.</span>
 See here my Lord what the diuell hath writ.</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 Giue it me my Lord, Ile show it to the King.</div>
<div class="dverse">Go sirs, see them fast lockt in prison. <span class="lnum">45</span>
 <span class="sd-verseend"><i>Exet</i> with them.</span></div>

<div class="dverse1"><span class="sd-cn">Bucking.</span>
 My Lord, I pray you let me go post vnto the King,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dad047" id="lnum-dad047">♦</a>
 Vnto S. Albones, to tell this newes.</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 Content. Away then, about it straight.</div>

<div class="dverse1"><span class="sd-cn">Buck.</span>
 Farewell my Lord. <span class="sd-verseend"><i>Exet</i> Buckingham.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dad050" id="lnum-dad050">50</a>
 <span class="sd-cn">Yorke.</span>
  Whose within there?</div>

<div class="sd-entry">Enter one.</div>

<div class="dprose1"><span class="sd-cn">One.</span> My Lord.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dad052" id="lnum-dad052">♦</a>
 <span class="sd-cn">Yorke.</span>
 Sirrha, go will the Earles of Salsbury and Warwicke, to sup with me to night. <span class="sd-proseend"><i>Exet</i> Yorke.</span></div>

<div class="dprose1"><span class="sd-cn">One.</span> I will my Lord. <span class="sd-verseend"><i>Exet.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> V.
<span class="dnavigatenf">dae</span></h3>

Enter the King and Queene with her Hawke on her fist, and Duke
<i>Humphrey</i> and <i>Suffolke</i>, and the Cardinall, as if they came from
hawking.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 My Lord, how did your grace like this last flight?</div>
<div class="dverse">But as <i>I</i> cast her off the winde did rise,</div>
<div class="dverse">And twas ten to one, old Ione had not gone out.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 How wonderful the Lords workes are on earth,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dae005" id="lnum-dae005">5</a>
 Euen in these silly creatures of his hands,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dae006" id="lnum-dae006">♦</a>
 Vnckle Gloster, how hie your Hawke did sore?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dae007" id="lnum-dae007">♦</a>
 And on a sodaine soust the Partridge downe.</div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 No maruell if it please your Maiestie</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dae009" id="lnum-dae009">♦</a>
 My Lord Protectors Hawke done towre so well,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dae010" id="lnum-dae010">10</a>
 He knowes his maister loues to be aloft.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae011" id="lnum-dae011">♦</a>
 <span class="sd-cn">Humphrey.</span>
  Faith my Lord, it is but a base minde</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dae012" id="lnum-dae012">♦</a>
 That can sore no higher than a Falkons pitch.</div>

<div class="dverse1"><span class="sd-cn">Card.</span>
 I thought your grace would be aboue the cloudes.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae014" id="lnum-dae014">♦</a>
 <span class="sd-cn">Humph.</span>
  I my Lord Cardinall, were it not good</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dae015" id="lnum-dae015">15</a>
 Your grace could fllie to heauen.</div>

<div class="dprose1"><span class="sd-cn">Card.</span>
 Thy heauen is on earth, thy words and thoughts beat on a Crowne, proude Protector dangerous Peere, to smooth it thus <a class="lnum pginternal" href="#lnote-dae018" id="lnum-dae018">♦</a>
 with King and common-wealth.</div>

<div class="dverse1"><span class="sd-cn">Humphrey.</span>
 How now my Lord, why this is more then needs,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dae020" id="lnum-dae020">20</a>
 Church-men so hote. Good vnckle can you doate.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae021" id="lnum-dae021">♦</a>
 <span class="sd-cn">Suffolke.</span>
  Why not Hauing so good a quarrell &amp; so bad a cause.</div>

<div class="dverse1"><span class="sd-cn">Humphrey.</span>
 As how, my Lord?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae023" id="lnum-dae023">♦</a>
 <span class="sd-cn">Suffolke.</span>
  As you, my Lord. And it like your Lordly</div>
<div class="dverse">Lords Protectorship.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Humphrey.</span>
  Why Suffolke, England knowes thy insolence.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 And thy ambition Gloster.</div>

<div class="dprose1"><span class="sd-cn">King.</span>
 Cease gentle Queene, and whet not on these furious Lordes to wrath, for blessed are the peace-makers on earth.</div>

<div class="dverse1"><span class="lnum">30</span>
 <span class="sd-cn">Card.</span>
  Let me be blessed for the peace I make,</div>
<div class="dverse">Against this proud Protector with my sword.</div>

<div class="dverse1"><span class="sd-cn">Humphrey.</span>
 Faith holy vnckle, I would it were come to that.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae033" id="lnum-dae033">♦</a>
 <span class="sd-cn">Cardinall.</span>
  Euen when thou darest.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dae034" id="lnum-dae034">♦</a>
 <span class="sd-cn">Humphrey.</span>
 Dare. I tell rhee Priest, Plantagenets could neuer <span class="lnum">35</span>
 brooke the dare.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dae036" id="lnum-dae036">♦</a>
 <span class="sd-cn">Card.</span>
 <i>I</i> am Plantaganet as well as thou, and sonne to Iohn of Gaunt.</div>

<div class="dverse1"><span class="sd-cn">Humph.</span>
 In Bastardie.</div>

<div class="dverse1"><span class="sd-cn">Cardin.</span>
 I scorne thy words.</div>

<div class="dverse1"><span class="sd-cn">Humph.</span>
 Make vp no factious numbers, but euen in thine own</div>
<div class="dverse">person meete me at the East end of the groue.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae042" id="lnum-dae042">♦</a>
 <span class="sd-cn">Card.</span>
  Heres my hand, I will.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Why how now Lords?</div>

<div class="dprose1"><span class="sd-cn">Card.</span>
 Faith Cousin Gloster, had not your man cast off so soone, <span class="lnum">45</span>
 we had had more sport to day, Come with thy swoord and buckler.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae047" id="lnum-dae047">♦</a>
 <span class="sd-cn">Humphrey.</span>
  Faith Priest, Ile shaue your Crowne.</div>

<div class="dverse1"><span class="sd-cn">Cardinall.</span>
 Protector, protect thy selfe well.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae049" id="lnum-dae049">♦</a>
 <span class="sd-cn">King.</span>
  The wind growes high, so doth your chollour Lords.</div>

<div class="sd-entry">Enter one crying, A miracle, a miracle.</div>

<div class="dverse"><a class="lnum pginternal" href="#lnote-dae050" id="lnum-dae050">50</a>
 How now, now sirrha, what miracle is it?</div>

<div class="dprose1"><span class="sd-cn">One.</span>
 And it please your grace, there is a man that came blinde <a class="lnum pginternal" href="#lnote-dae052" id="lnum-dae052">♦</a>
 to S. Albones, and hath receiued his sight at his shrine.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dae053" id="lnum-dae053">♦</a>
 <span class="sd-cn">King.</span>
 Goe fetch him hither, that wee may glorifie the Lord with him.</div>

<div class="sd-entry">Enter the Maior of Saint Albones and his brethren with Musicke, bearing the man that had bene blind, betweene two in a chaire.</div>

<div class="dverse1"><span class="lnum">55</span>
 <span class="sd-cn">King.</span>
  Thou happie man, giue God eternall praise,</div>
<div class="dverse">For he it is, that thus hath helped thee.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae057" id="lnum-dae057">♦</a>
 <span class="sd-cn">Humphrey.</span>
  Where wast thou borne?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae058" id="lnum-dae058">♦</a>
 <span class="sd-cn">Poore man.</span>
 At <i>Barwicke</i> sir, in the North.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae059" id="lnum-dae059">♦</a>
 <span class="sd-cn">Humph.</span>
 At <i>Barwicke</i>, and come thus far for helpe.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae060" id="lnum-dae060">60</a>
 <span class="sd-cn">Poore man.</span>
  I sir, it was told me in my sleepe,</div>
<div class="dverse">That sweet saint Albones, should giue me my sight againe.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae062" id="lnum-dae062">♦</a>
 <span class="sd-cn">Humphrey.</span>
  What art thou lame too?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae063" id="lnum-dae063">♦</a>
 <span class="sd-cn">Poore man.</span>
  I indeed sir, God helpe me.</div>

<div class="dverse1"><span class="sd-cn">Humphrey.</span>
 How cam’st thou lame?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae065" id="lnum-dae065">65</a>
 <span class="sd-cn">Poore man.</span>
  With falling off on a plum-tree.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae066" id="lnum-dae066">♦</a>
 <span class="sd-cn">Humph.</span>
  Wart thou blind &amp; wold clime plumtrees?</div>

<div class="dverse1"><span class="sd-cn">Poore man.</span>
 Neuer but once sir in all my life,</div>
<div class="dverse">My wife did long for plums.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae069" id="lnum-dae069">♦</a>
 <span class="sd-cn">Humph.</span>
  But tell me, wart thou borne blinde?</div>

<div class="dverse1"><span class="lnum">70</span>
 <span class="sd-cn">Poore man.</span>  <i>I</i> truly sir.</div>

<div class="dverse1"><span class="sd-cn">Woman.</span>
 I indeed sir, he was borne blinde.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae072" id="lnum-dae072">♦</a>
 <span class="sd-cn">Humphrey.</span>
  What art thou his mother?</div>

<div class="dverse1"><span class="sd-cn">Woman.</span>
 His wife sir.</div>

<div class="dverse1"><span class="sd-cn">Humphrey.</span>
 Hadst thou bene his mother,</div>
<div class="dverse"><span class="lnum">75</span>
 Thou couldst haue better told.</div>
<div class="dverse">Why let me see, I thinke thou canst not see yet.</div>

<div class="dverse1"><span class="sd-cn">Poore man.</span>
 Yes truly maister, as cleare as day.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae078" id="lnum-dae078">♦</a>
 <span class="sd-cn">Humphrey.</span>
  Saist thou so. What colours his cloake?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae079" id="lnum-dae079">♦</a>
 <span class="sd-cn">Poore man.</span>
  Why red maister, as red as blood.</div>

<div class="dverse1"><span class="lnum">80</span>
 <span class="sd-cn">Humphrey.</span>
  And his cloake?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae081" id="lnum-dae081">♦</a>
 <span class="sd-cn">Poore man.</span>
  Why thats greene.</div>

<div class="dverse1"><span class="sd-cn">Humphrey.</span>
 And what colours his hose?</div>

<div class="dverse1"><span class="sd-cn">Poore man.</span>
 Yellow maister, yellow as gold.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae084" id="lnum-dae084">♦</a>
 <span class="sd-cn">Humphrey.</span>
  And what colours my gowne?</div>

<div class="dverse1"><span class="lnum">85</span>
 <span class="sd-cn">Poore man.</span>
  Blacke sir, as blacke as Ieat.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Then belike he knowes what colour Ieat is on.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae087" id="lnum-dae087">♦</a>
 <span class="sd-cn">Suffolke.</span>
 And yet <i>I</i> thinke Ieat did he neuer see.</div>

<div class="dverse1"><span class="sd-cn">Humph.</span>
 But cloakes and gownes ere this day many a (one.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dae089" id="lnum-dae089">♦</a>
 But tell me sirrha, whats my name?</div>

<div class="dverse1"><span class="lnum">90</span>
 <span class="sd-cn">Poore man.</span>
  Alasse maister I know not.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae091" id="lnum-dae091">♦</a>
 <span class="sd-cn">Humphrey.</span>
  Whats his name?</div>

<div class="dverse1"><span class="sd-cn">Poore man.</span>
 <i>I</i> know not.</div>

<div class="dverse1"><span class="sd-cn">Humphrey.</span>
 Nor his?</div>

<div class="dverse1"><span class="sd-cn">Poore man.</span>
 No truly sir.</div>

<div class="dverse1"><span class="lnum">95</span>
 <span class="sd-cn">Humphrey</span>
  Nor his name?</div>

<div class="dverse1"><span class="sd-cn">Poore man</span>
 No indeed maister.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae097" id="lnum-dae097">♦</a>
 <span class="sd-cn">Humphrey</span>
  Whats thine owne name?</div>

<div class="dverse1"><span class="sd-cn">Poore man.</span>
 <i>Sander</i>, and it please you maister.</div>

<div class="dprose1"><span class="sd-cn">Humphrey.</span>
 Then Sander sit there, the lyingest knaue in <a class="lnum pginternal" href="#lnote-dae100" id="lnum-dae100">100</a>
 Christendom. If thou hadst bene born blind, thou mightest aswell haue knowne all our names, as thus to name the seuerall colours we doo weare. Sight may distinguish of colours, but sodeinly to nominate <a class="lnum pginternal" href="#lnote-dae103" id="lnum-dae103">♦</a>
 them all, it is impossible. My Lords, saint Albones here hath done a Miracle, and would you not thinke his cunning to be great, that <a class="lnum pginternal" href="#lnote-dae105" id="lnum-dae105">105</a>
 could restore this Cripple to his legs againe.</div>

<div class="dverse1"><span class="sd-cn">Poore man.</span>
 Oh maister I would you could.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae107" id="lnum-dae107">♦</a>
 <span class="sd-cn">Humphrey.</span>
  My Maisters of saint Albones,</div>
<div class="dverse">Haue you not Beadles in your Towne,</div>
<div class="dverse">And things called whippes?</div>

<div class="dverse1"><span class="lnum">110</span>
 <span class="sd-cn">Mayor.</span>
  Yes my Lord, if it please your grace.</div>

<div class="dverse1"><span class="sd-cn">Humph.</span>
 Then send for one presently.</div>

<div class="dverse1"><span class="sd-cn">Mayor.</span>
 Sirrha, go fetch the Beadle hither straight. <span class="sd-verseend"><i>Exet</i> one.</span></div>

<div class="dverse1"><span class="sd-cn">Humph.</span>
 Now fetch me a stoole hither by and by.</div>
<div class="dverse">Now sirrha, If you meane to saue your selfe from whipping,</div>
<div class="dverse"><span class="lnum">115</span>
 Leape me ouer this stoole and runne away.</div>

<div class="sd-entry">Enter Beadle.</div>

<div class="dverse1"><span class="sd-cn">Poore man.</span>
 Alasse maister I am not able to stand alone,</div>
<div class="dverse">You go about to torture me in vaine.</div>

<div class="dverse1"><span class="sd-cn">Humph.</span>
 Well sir, we must haue you finde your legges.</div>
<div class="dverse">Sirrha Beadle, whip him till he leape ouer that same stoole.</div>

<div class="dprose1"><span class="lnum">120</span>
 <span class="sd-cn">Beadle.</span>
 I will my Lord, come on sirrha, off with your doublet quickly.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dae122" id="lnum-dae122">♦</a>
 <span class="sd-cn">Poore man.</span>
 Alas maister what shall <i>I</i> do, I am not able to stand. <span class="sd-proseend">After the Beadle hath hit him one girke, he leapes ouer the stoole and runnes away, and they run after him, crying, A miracle, a miracle.</span></div>

<div class="dprose1"><span class="sd-cn">Hump.</span>
 Amiracle, a miracle, let him be taken againe, &amp; whipt through euery Market Towne til he comes at Barwicke where he <span class="lnum">125</span> was borne.</div>

<div class="dverse1"><span class="sd-cn">Mayor.</span>
 It shall be done my Lord. <span class="sd-verseend"><i>Exet</i> Mayor.</span></div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 My Lord Protector hath done wonders to day,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dae128" id="lnum-dae128">♦</a>
 He hath made the blinde to see, and halt to go.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae129" id="lnum-dae129">♦</a>
 <span class="sd-cn">Humph.</span>
  I but you did greater wonders, when you made whole</div>
<div class="dverse"><span class="lnum">130</span>
 Dukedomes flie in a day.</div>
<div class="dverse">Witnesse <i>France</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae132" id="lnum-dae132">♦</a>
 <span class="sd-cn">King.</span>
  Haue done I say, and let me here no more of that.</div>

<div class="sd-entry">Enter the Duke of <i>Buckingham</i>.</div>

<div class="dverse"><a class="lnum pginternal" href="#lnote-dae133" id="lnum-dae133">♦</a>
 What newes brings Duke Humprey of Buckingham?</div>

<div class="dverse1"><span class="sd-cn">Buck.</span>
 Ill newes for some my Lord, and this it is,</div>
<div class="dverse"><span class="lnum">135</span>
 That proud dame Elnor our Protectors wife,</div>
<div class="dverse">Hath plotted Treasons gainst the King and Peeres,</div>
<div class="dverse">By wichcrafts, sorceries, and cuniurings,</div>
<div class="dverse">Who by such meanes did raise a spirit vp,</div>
<div class="dverse">To tell her what hap should betide the state,</div>
<div class="dverse"><span class="lnum">140</span>
 But ere they had finisht their diuellish drift,</div>
<div class="dverse">By Yorke and my selfe they were all surprisde,</div>
<div class="dverse">And heres the answere the diuel did make to them.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 First of the King, what shall become of him?</div>

<div class="dverse1"><span class="sd-cn">Reads.</span>
 The Duke yet liues, that Henry shal depose,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dae145" id="lnum-dae145">145</a>
 Yet him out liue, and die a violent death.</div>
<div class="dverse">Gods will be done in all.</div>
<div class="dverse">What fate awaits the Duke of Suffolke?</div>
<div class="dverse">By water shall he die and take his end.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae149" id="lnum-dae149">♦</a>
 <span class="sd-cn">Suffolke.</span>
  By water must the Duke of Suffolke die?</div>
<div class="dverse"><span class="lnum">150</span>
 It must be so, or else the diuel doth lie.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Let Somerset shun Castles,</div>
<div class="dverse">For safer shall he be vpon the sandie plaines,</div>
<div class="dverse">Then where Castles mounted stand.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dae154" id="lnum-dae154">♦</a>
 <span class="sd-cn">Card.</span>
  Heres good stuffe, how now my Lord Protector</div>
<div class="dverse"><span class="lnum">155</span>
 This newes I thinke hath turnde your weapons point,</div>
<div class="dverse">I am in doubt youle scarsly keepe your promise.</div>

<div class="dverse1"><span class="sd-cn">Humphrey.</span>
 Forbeare ambitious Prelate to vrge my griefe,</div>
<div class="dverse">And pardon me my gratious Soueraigne,</div>
<div class="dverse">For here I sweare vnto your Maiestie,</div>
<div class="dverse"><span class="lnum">160</span>
 That I am guiltlesse of these hainous crimes</div>
<div class="dverse">Which my ambitious wife hath falsly done,</div>
<div class="dverse">And for she would betraie her soueraigne Lord,</div>
<div class="dverse">I here renounce her from my bed and boord,</div>
<div class="dverse">And leaue her open for the law to iudge,</div>
<div class="dverse"><span class="lnum">165</span>
 Vnlesse she cleare her selfe of this foule deed.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Come my Lords this night weele lodge in S. Albones,</div>
<div class="dverse">And to morrow we will ride to London,</div>
<div class="dverse">And trie the vtmost of these Treasons forth,</div>
<div class="dverse">Come vnckle Gloster along with vs,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dae170" id="lnum-dae170">170</a>
 My mind doth tell me thou art innocent. <span class="sd-verseend"><i>Exet omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> VI.
 <span class="dnavigatenf">daf</span></h3>

Enter the Duke of <i>Yor</i>k<i>e</i>, and the Earles of <i>Salsbury</i> and
<i>Warwicke</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daf001" id="lnum-daf001">♦</a>
 <span class="sd-cn">Yorke.</span>
  My Lords our simple supper ended, thus,</div>
<div class="dverse">Let me reueale vnto your honours here,</div>
<div class="dverse">The right and title of the house of Yorke,</div>
<div class="dverse">To Englands Crowne by liniall desent.</div>

<div class="dverse1"><span class="lnum">5</span>
 <span class="sd-cn">War.</span>
  Then Yorke begin, and if thy claime be good,</div>
<div class="dverse">The Neuils are thy subiects to command.</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 Then thus my Lords.</div>
<div class="dverse">Edward the third had seuen sonnes,</div>
<div class="dverse">The first was Edward the blacke Prince,</div>
<div class="dverse"><span class="lnum">10</span>
 Prince of Wales.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daf011" id="lnum-daf011">♦</a>
 The second was Edmund of Langly,</div>
<div class="dverse">Duke of Yorke.</div>
<div class="dverse">The third was Lyonell Duke of Clarence.</div>
<div class="dverse">The fourth was Iohn of Gaunt,</div>
<div class="dverse"><span class="lnum">15</span>
 The Duke of Lancaster.</div>
<div class="dverse">The fifth was Roger Mortemor, Earle of March.</div>
<div class="dverse">The sixt was sir Thomas of Woodstocke,</div>
<div class="dverse">William of Winsore was the seuenth and last.</div>

<div class="dprose">Now, Edward the blacke Prince he died before his
father, and left <span class="lnum">20</span> the behinde him Richard,
that afterwards was King, Crownde by name of Richard the second, and he
died without an heire. Edmund of Langly Duke of Yorke died, and left
behind him two daughters, Anne and Elinor.</div>

<div class="dprose" id="lnum-daf024">Lyonell Duke of Clarence died, and left behinde
Alice, Anne, and <span class="lnum">25</span> Elinor, that was
after married to my father, and by her I claime the Crowne, as the
true heire to Lyonell Duke <a class="lnum pginternal" href="#lnote-daf027" id="lnum-daf027">♦</a> of Clarence, the third sonne to Edward
the third. Now sir. In the <a class="lnum pginternal" href="#lnote-daf028" id="lnum-daf028">♦</a> time of Richards raigne, Henry of Bullingbrooke,
sonne and heire to Iohn of Gaunt, the Duke of Lancaster fourth sonne to
Edward <span class="lnum">30</span> the third, he claimde the Crowne,
deposde the Merthfull King, and <a class="lnum pginternal" href="#lnote-daf031" id="lnum-daf031">♦</a> as both you know, in Pomphret Castle harmlesse
Richard was shamefully murthered, and so by Richards death came the
house of Lancaster vnto the Crowne.</div>

<div class="dprose1"><span class="sd-cn">Sals.</span>
 Sauing your tale my Lord, as I haue heard, in the raigne <span class="lnum">35</span>
 of Bullenbrooke, the Duke of Yorke did claime the Crowne, and <a class="lnum pginternal" href="#lnote-daf036" id="lnum-daf036">♦</a>
 but for Owin Glendor, had bene King.</div>

<div class="dprose1"><span class="sd-cn">Yorke.</span>
 True. But so it fortuned then, by meanes of that monstrous rebel Glendor, the noble Duke of York was done to death, and so euer since the heires of Iohn of Gaunt haue possessed the <a class="lnum pginternal" href="#lnote-daf040" id="lnum-daf040">40</a>
 Crowne. But if the issue of the elder should sucseed before the issue of the yonger, then am I lawfull heire vnto the kingdome.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-daf042" id="lnum-daf042">♦</a>
 <span class="sd-cn">Warwicke.</span>
 What plaine proceedings can be more plaine, hee claimes it from Lyonel Duke of Clarence, the third sonne to Edward the third, and Henry from Iohn of Gaunt the fourth sonne. <span class="lnum">45</span>
 So that till Lyonels issue failes, his should not raigne. It failes not yet, but florisheth in thee &amp; in thy sons, braue slips of such a stock. Then noble father, kneele we both togither, and in this priuate place, be we the first to honor him with birthright to the Crown.</div>

<div class="dprose1"><span class="sd-cn">Both.</span>
 Long liue Richard Englands royall King.</div>

<div class="dprose1"><span class="lnum">50</span>
 <span class="sd-cn">Yorke.</span>
 I thanke you both. But Lords I am not your King, vntil this sword be sheathed euen in the hart blood of the house of Lancaster.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Then Yorke aduise thy selfe and take thy time,</div>
<div class="dverse">Claime thou the Crowne, and set thy standard vp,</div>
<div class="dverse"><span class="lnum">55</span>
 And in the same aduance the milke-white Rose,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daf056" id="lnum-daf056">♦</a>
 And then to gard it, will I rouse the Beare,</div>
<div class="dverse">Inuiron’d with ten thousand Ragged-staues</div>
<div class="dverse">To aide and helpe thee for to win thy right,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daf059" id="lnum-daf059">♦</a>
 Maugre the proudest Lord of Henries blood,</div>
<div class="dverse"><span class="lnum">60</span>
 That dares deny the right and claime of Yorke,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daf061" id="lnum-daf061">♦</a>
 For why my minde presageth I shall liue</div>
<div class="dverse">To see the noble Duke of Yorke to be a King.</div>

<div class="dprose1"><span class="sd-cn">Yorke.</span>
 Thanks noble Warwicke, and Yorke doth hope to see, The Earl of Warwicke liue, to be the greatest man in England, <a class="lnum pginternal" href="#lnote-daf065" id="lnum-daf065">65</a>
 but the King. Come lets goe. <span class="sd-proseend"><i>Exet omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> VII.
<span class="dnavigatenf">dag</span></h3>

Enter King <i>Henry</i>, and the Queene, Duke <i>Humphrey</i>, the Duke of <i>Suffolke</i>, and the Duke of <i>Buckingham</i>, the <i>Cardinall</i>, and Dame <i>Elnor Cobham</i>, led with the Officers, and then enter to them the Duke of <i>Yorke</i>, and the Earles of <i>Salsbury</i> and <i>Warwicke</i>.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dag001" id="lnum-dag001">♦</a>
 <span class="sd-cn">King.</span>
 Stand foorth Dame Elnor Cobham Duches of Gloster, <a class="lnum pginternal" href="#lnote-dag002" id="lnum-dag002">♦</a>
 and here the sentence pronounced against thee for these Treasons, <a class="lnum pginternal" href="#lnote-dag003" id="lnum-dag003">♦</a>
 that thou hast committed gainst vs, our States and Peeres.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dag004" id="lnum-dag004">♦</a>
 First for thy hainous crimes, thou shalt two daies in London do <span class="lnum">5</span>
 penance barefoote in the streetes, with a white sheete about thy bodie, and a waxe Taper burning in thy hand. That done, thou shalt be banished for euer into the Ile of Man, there to ende thy <a class="lnum pginternal" href="#lnote-dag008" id="lnum-dag008">♦</a>
 wretched daies, and this is our sentence erreuocable. Away with her.</div>

<div class="dverse1"><span class="lnum">10</span>
 <span class="sd-cn">Elnor.</span>
 Euen to my death, for I haue liued too long.
 <span class="sd-verseend"><i>Exet</i> some with <i>Elnor</i>.</span></div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Greeue not noble vnckle, but be thou glad,</div>
<div class="dverse">In that these Treasons thus are come to light,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dag013" id="lnum-dag013">♦</a>
 Least God had pourde his vengeance on thy head,</div>
<div class="dverse">For her offences that thou heldst so deare.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dag015" id="lnum-dag015">15</a>
 <span class="sd-cn">Humph.</span>
 Oh gratious <i>Henry</i>, giue me leaue awhile,</div>
<div class="dverse">To leaue your grace, and to depart away,</div>
<div class="dverse">For sorrowes teares hath gripte my aged heart,</div>
<div class="dverse">And makes the fountaines of mine eyes to swell,</div>
<div class="dverse">And therefore good my Lord, let me depart.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dag020" id="lnum-dag020">20</a>
 <span class="sd-cn">King.</span>
  With all my hart good vnkle, when you please,</div>
<div class="dverse">Yet ere thou goest, <i>Humphrey</i> resigne thy staffe,</div>
<div class="dverse">For Henry will be no more protected,</div>
<div class="dverse">The Lord shall be my guide both for my land and me.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dag024" id="lnum-dag024">♦</a>
 <span class="sd-cn">Humph.</span>
  My staffe, I noble Henry, my life and all.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dag025" id="lnum-dag025">25</a>
 My staffe, I yeeld as willing to be thine,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dag026" id="lnum-dag026">♦</a>
 As erst thy noble father made it mine,</div>
<div class="dverse">And euen as willing at thy feete I leaue it,</div>
<div class="dverse">As others would ambitiously receiue it,</div>
<div class="dverse">And long hereafter when I am dead and gone,</div>
<div class="dverse"><span class="lnum">30</span>
 May honourable peace attend thy throne.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Vnkle Gloster, stand vp and go in peace,</div>
<div class="dverse">No lesse beloued of vs, then when</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dag033" id="lnum-dag033">♦</a>
 Thou weart Protector ouer my land. <span class="sd-verseend"><i>Exet Gloster.</i></span></div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 Take vp the staffe, for here it ought to stand,</div>
<div class="dverse"><span class="lnum">35</span>
 Where should it be, but in King Henries hand?</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 Please it your Maiestie, this is the day</div>
<div class="dverse">That was appointed for the combating</div>
<div class="dverse">Betweene the Armourer and his man, my Lord,</div>
<div class="dverse">And they are readie when your grace doth please.</div>

<div class="dverse1"><span class="lnum">40</span>
 <span class="sd-cn">King.</span>
  Then call them forth, that they may trie their rightes.</div>

<div class="sd-entry">Enter at one doore the Armourer and his neighbours, drinking to him so much that he is drunken, and he enters with a drum before him, and his staffe with a sand-bag fastened to it, and at the other doore, his man with a drum and sand-bagge, and Prentises drinking to him.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dag041" id="lnum-dag041">♦</a>
 <span class="sd-cn">1. Neighbor.</span>
  Here neighbor Hornor, I drink to you in a cup of (Sacke.</div>
<div class="dverse">And feare not neighbor, you shall do well inough.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dag043" id="lnum-dag043">♦</a>
 <span class="sd-cn">2. Neigh.</span>
  And here neighbor, heres a cup of Charneco.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dag044" id="lnum-dag044">♦</a>
 <span class="sd-cn">3. Neigh.</span>
  Heres a pot of good double beere, neighbor drinke</div>
<div class="dverse"><span class="lnum">45</span>
 And be merry, and feare not your man.</div>

<div class="dverse1"><span class="sd-cn">Armourer.</span>
 Let it come, yfaith ile pledge you all,</div>
<div class="dverse">And a figge for Peter.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dag048" id="lnum-dag048">♦</a>
 <span class="sd-cn">1. Prentise.</span>
  Here Peter I drinke to thee, and be not affeard.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dag049" id="lnum-dag049">♦</a>
 <span class="sd-cn">2. Pren.</span>
  Here Peter, heres a pinte of Claret-wine for thee.</div>

<div class="dverse1"><span class="lnum">50</span>
 <span class="sd-cn">3. Pren.</span>
  And heres a quart for me, and be merry Peter,</div>
<div class="dverse">And feare not thy maister, fight for credit of the Prentises.</div>

<div class="dverse1"><span class="sd-cn">Peter.</span>
 I thanke you all, but ile drinke no more,</div>
<div class="dverse">Here Robin, and if I die, here I giue thee my hammer,</div>
<div class="dverse">And Will, thou shalt haue my aperne, and here Tom,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dag055" id="lnum-dag055">55</a>
 Take all the mony that I haue.</div>

<div class="dprose1">O Lord blesse me, I pray God, for I am neuer able to deale with <a class="lnum pginternal" href="#lnote-dag057" id="lnum-dag057">♦</a>
 my maister, he hath learnt so much fence alreadie.</div>

<div class="dverse1"><span class="sd-cn">Salb.</span>
 Come leaue your drinking, and fall to blowes.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dag059" id="lnum-dag059">♦</a>
 Sirrha, whats thy name?</div>

<div class="dverse1"><span class="lnum">60</span>
 <span class="sd-cn">Pettr.</span>
  Peter forsooth.</div>

<div class="dverse1"><span class="sd-cn">Salbury.</span>
 Peter, what more?</div>

<div class="dverse1"><span class="sd-cn">Peter.</span>
 <i>Thumpe</i>.</div>

<div class="dverse1"><span class="sd-cn">Salsbury.</span>
 Thumpe, then see that thou thumpe thy maister.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dag064" id="lnum-dag064">♦</a>
 <span class="sd-cn">Armour.</span>
 Heres to thee neighbour, fill all the pots again, for before <span class="lnum">65</span>
 we fight, looke you, I will tell you my minde, for I am come <a class="lnum pginternal" href="#lnote-dag066" id="lnum-dag066">♦</a>
 hither as it were of my mans instigation, to proue my selfe an honest man, and Peter a knaue, and so haue at you Peter with downright blowes, as Beuys of South-hampton fell vpon Askapart.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dag069" id="lnum-dag069">♦</a>
 <span class="sd-cn">Peter.</span>
  Law you now, I told you hees in his fence alreadie.</div>
<div class="dverse">Alarmes, and Peter hits him on the head and fels him.</div>

<div class="dverse1"><span class="lnum">70</span>
 <span class="sd-cn">Armou.</span>
 Hold Peter, I confesse, Treason, treason. <span class="sd-verseend">He dies.</span></div>

<div class="dverse1"><span class="sd-cn">Peter.</span>
 O God I giue thee praise. <span class="sd-verseend">He kneeles downe.</span></div>

<div class="dverse1"><span class="sd-cn">Pren.</span>
 Ho well done Peter. God saue the King.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Go take hence that Traitor from our sight,</div>
<div class="dverse">For by his death we do perceiue his guilt,</div>
<div class="dverse"><span class="lnum">75</span>
 And God in iustice hath reuealde to vs,</div>
<div class="dverse">The truth and innocence of this poore fellow,</div>
<div class="dverse">Which he had thought to haue murthered wrongfully.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dag078" id="lnum-dag078">♦</a>
 Come fellow, follow vs for thy reward. <span class="sd-verseend"><i>Exet omnis.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> VIII.
<span class="dnavigatenf">dah</span></h3>

Enter Duke <i>Humphrey</i> and his men, in mourning cloakes.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dah001" id="lnum-dah001">♦</a>
 <span class="sd-cn">Humph.</span>
  Sirrha, whats a clocke?</div>

<div class="dverse1"><span class="sd-cn">Seruing.</span>
 Almost ten my Lord.</div>

<div class="dverse1"><span class="sd-cn">Humph.</span>
 Then is that wofull houre hard at hand,</div>
<div class="dverse">That my poore Lady should come by this way,</div>
<div class="dverse"><span class="lnum">5</span>
 In shamefull penance wandring in the streetes,</div>
<div class="dverse">Sweete Nell, ill can thy noble minde abrooke,</div>
<div class="dverse">The abiect people gazing on thy face,</div>
<div class="dverse">With enuious lookes laughing at thy shame,</div>
<div class="dverse">That earst did follow thy proud Chariot wheeles,</div>
<div class="dverse"><span class="lnum">10</span>
 When thou didst ride in tryumph through the streetes.</div>

<div class="sd-entry">Enter Dame <i>Elnor Cobham</i>, bare-foote, and a white sheete about her, with a waxe candle in her hand, and verses written on her backe and pind on, and accompanied with the Sheriffes of London, and Sir <i>Iohn Standly</i>, and Officers, with billes and holbards.</div>

<div class="dverse1"><span class="sd-cn">Seruing.</span>
 My gratious Lord, see where my Lady comes,</div>
<div class="dverse">Please it your grace, weele take her from the Sheriffes?</div>

<div class="dverse1"><span class="sd-cn">Humph.</span>
 I charge you for your liues stir not a foote,</div>
<div class="dverse">Nor offer once to draw a weapon here,</div>
<div class="dverse"><span class="lnum">15</span>
 But let them do their office as they should.</div>

<div class="dverse1"><span class="sd-cn">Elnor.</span>
 Come you my Lord to see my open shame?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dah017" id="lnum-dah017">♦</a>
 Ah Gloster, now thou doest penance too,</div>
<div class="dverse">See how the giddie people looke at thee,</div>
<div class="dverse">Shaking their heads, and pointing at thee heere,</div>
<div class="dverse"><span class="lnum">20</span>
 Go get thee gone, and hide thee from their sights,</div>
<div class="dverse">And in thy pent vp studie rue my shame,</div>
<div class="dverse">And ban thine enemies. Ah mine and thine.</div>

<div class="dverse1"><span class="sd-cn">Hum.</span>
 Ah Nell, sweet Nell, forget this extreme grief,</div>
<div class="dverse">And beare it patiently to ease thy heart.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Elnor.</span>
  Ah Gloster teach me to forget my selfe,</div>
<div class="dverse">For whilst I thinke I am thy wedded wife,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dah027" id="lnum-dah027">♦</a>
 Then thought of this, doth kill my wofull heart.</div>
<div class="dverse">The ruthlesse flints do cut my tender feete,</div>
<div class="dverse">And when I start the cruell people laugh,</div>
<div class="dverse"><span class="lnum">30</span>
 And bids me be aduised how I tread,</div>
<div class="dverse">And thus with burning Taper in my hand,</div>
<div class="dverse">Malde vp in shame with papers on my backe,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dah033" id="lnum-dah033">♦</a>
 Ah, Gloster, can I endure this and liue.</div>
<div class="dverse">Sometime ile say I am Duke <i>Humphreys</i> wife,</div>
<div class="dverse"><span class="lnum">35</span>
 And he a Prince, Protector of the land,</div>
<div class="dverse">But so he rulde, and such a Prince he was,</div>
<div class="dverse">As he stood by, whilst I his forelorne Duches</div>
<div class="dverse">Was led with shame, and made a laughing stocke,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dah039" id="lnum-dah039">♦</a>
 To euery idle rascald follower.</div>

<div class="dverse1"><span class="lnum">40</span>
 <span class="sd-cn">Humphrey.</span>
  My louely Nell, what wouldst thou haue me do?</div>
<div class="dverse">Should I attempt to rescue thee from hence,</div>
<div class="dverse">I should incurre the danger of the law,</div>
<div class="dverse">And thy disgrace would not be shadowed so.</div>

<div class="dverse1"><span class="sd-cn">Elnor.</span>
 Be thou milde, and stir not at my disgrace,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dah045" id="lnum-dah045">45</a>
 Vntill the axe of death hang ouer thy head,</div>
<div class="dverse">As shortly sure it will. For Suffolke he,</div>
<div class="dverse">The new made Duke, that may do all in all</div>
<div class="dverse">With her that loues him so, and hates vs all,</div>
<div class="dverse">And impious Yorke and Bewford that false Priest,</div>
<div class="dverse"><span class="lnum">50</span>
 Haue all lymde bushes to betraie thy wings,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dah051" id="lnum-dah051">♦</a>
 And flie thou how thou can they will intangle thee.</div>

<div class="sd-entry">Enter a Herald of Armes.</div>

<div class="dprose1"><span class="sd-cn">Herald.</span>
 I summon your Grace, vnto his highnesse Parlament
 <a class="lnum pginternal" href="#lnote-dah053" id="lnum-dah053">♦</a>
 holden at saint Edmunds-Bury, the first of the next month.</div>

<div class="dverse1"><span class="sd-cn">Humphrey.</span>
 A Parlament and our consent neuer craude</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dah055" id="lnum-dah055">55</a>
 Therein before. This is sodeine.</div>
<div class="dverse">Well, we will be there.
 <span class="sd-verseend"><i>Exet. Herald.</i></span></div>
<div class="dverse"><span class="i04"> </span>
 Maister Sheriffe, I pray proceede no further against my
 Lady, then the course of law extendes.</div>

<div class="dverse1"><span class="sd-cn">Sheriffe.</span>
 Please it your grace, my office here doth end,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dah060" id="lnum-dah060">60</a>
 And I must deliuer her to sir Iohn Standly,</div>
<div class="dverse">To be conducted into the Ile of Man.</div>

<div class="dverse1"><span class="sd-cn">Humphrey.</span>
 Must you sir Iohn conduct my Lady?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dah063" id="lnum-dah063">♦</a>
 <span class="sd-cn">Standly.</span>
 <i>I</i> my gratious Lord, for so it is decreede,</div>
<div class="dverse">And <i>I</i> am so commanded by the King.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dah065" id="lnum-dah065">65</a>
 <span class="sd-cn">Humph.</span>
 <i>I</i> pray you sir Iohn, vse her neare the worse,</div>
<div class="dverse">In that <i>I</i> intreat you to vse her well.</div>
<div class="dverse">The world may smile againe and I may liue,</div>
<div class="dverse">To do you fauour if you do it her,</div>
<div class="dverse">And so sir Iohn farewell.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dah070" id="lnum-dah070">70</a>
 <span class="sd-cn">Elnor.</span>
  What gone my Lord, and bid me not farwell?</div>

<div class="dverse1"><span class="sd-cn">Humph.</span>
 Witnesse my bleeding heart, I cannot stay to speake. <span class="sd-verseend"><i>Exet Hnmphrey</i> and his men.</span></div>

<div class="dverse1"><span class="sd-cn">Elnor.</span>
 Then is he gone, is noble Gloster gone,</div>
<div class="dverse">And doth Duke Humphrey now forsake me too?</div>
<div class="dverse">Then let me haste from out faire Englands boundes,</div>
<div class="dverse"><span class="lnum">75</span>
 Come Standly come, and let vs haste away.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dah076" id="lnum-dah076">♦</a>
 <span class="sd-cn">Standly.</span>
  Madam lets go vnto some house hereby,</div>
<div class="dverse">Where you may shift your selfe before we go.</div>

<div class="dverse1"><span class="sd-cn">Elnor.</span>
 Ah good sir Iohn, my shame cannot be hid,</div>
<div class="dverse">Nor put away with casting off my sheete:</div>
<div class="dverse"><span class="lnum">80</span>
 But come let vs go, maister Sheriffe farewell,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dah081" id="lnum-dah081">♦</a>
 Thou hast but done thy office as thou shoulst.
 <span class="sd-verseend"><i>Exet omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> IX.
<span class="dnavigatenf">dai</span></h3>

Enter to the Parlament.</div>

<div class="sd-schg">Enter two Heralds before, then the Duke of
<i>Buckingham</i>, and the Duke of <i>Suffolke</i>, and then the Duke of <i>Yorke</i>,
and the <i>Cardinall</i> of <i>Winchester</i>, and then the King and the Oueene,
and then the Earle of <i>Salisbury</i>, and the Earle of <i>Warwicke</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dai001" id="lnum-dai001">♦</a>
 <span class="sd-cn">King.</span>
  I wonder our vnkle Gloster staies so long.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dai002" id="lnum-dai002">♦</a>
 <span class="sd-cn">Queene.</span>
  Can you not see, or will you not perceiue,</div>
<div class="dverse">How that ambitious Duke doth vse himselfe?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai004" id="lnum-dai004">♦</a>
 The time hath bene, but now that time is past.</div>
<div class="dverse"><span class="lnum">5</span>
 That none so humble as Duke Humphrey was.</div>
<div class="dverse">But now let one meete him euen in the morne,</div>
<div class="dverse">When euery one will giue the time of day,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai008" id="lnum-dai008">♦</a>
 And he will neither moue nor speake to vs.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai009" id="lnum-dai009">♦</a>
 See you not how the Commons follow him</div>
<div class="dverse"><span class="lnum">10</span>
 In troupes, crying, God saue the good Duke Humphrey,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai011" id="lnum-dai011">♦</a>
 And with long life, Iesus preserue his grace,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai012" id="lnum-dai012">♦</a>
 Honouring him as if he were their King.</div>
<div class="dverse">Gloster is no litle man in England,</div>
<div class="dverse">And if he list to stir commotions,</div>
<div class="dverse"><span class="lnum">15</span>
 Tys likely that the people will follow him.</div>
<div class="dverse">My Lord, if you imagine there is no such thing,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai017" id="lnum-dai017">♦</a>
 Then let it passe, and call it a womans feare.</div>
<div class="dverse">My Lord of Suffolke, Buckingham, and Yorke,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai019" id="lnum-dai019">♦</a>
 Disproue my Alligations if you can,</div>
<div class="dverse"><span class="lnum">20</span>
 And by your speeches, if you can reproue me,</div>
<div class="dverse">I will subscribe and say, I wrong’d the Duke.</div>

<div class="dverse1"><span class="sd-cn">Suffol.</span>
 Well hath your grace foreseen into that Duke,</div>
<div class="dverse">And if I had bene licenst first to speake,</div>
<div class="dverse">I thinke I should haue told your graces tale.</div>
<div class="dverse"><span class="lnum">25</span>
 Smooth runs the brooke whereas the streame is deepest</div>
<div class="dverse">No, no, my soueraigne, Gloster is a man</div>
<div class="dverse">Vnsounded yet, and full of deepe deceit.</div>

<div class="sd-entry">Enter the Duke of <i>Somerset</i>.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Welcome Lord Somerset, what newes from France?</div>

<div class="dverse1"><span class="sd-cn">Somer.</span>
 Cold newes my Lord, and this it is,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai030" id="lnum-dai030">30</a>
 That all your holds and Townes within those Territores</div>
<div class="dverse">Is ouercome my Lord, all is lost.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Cold newes indeed Lord Somerset,</div>
<div class="dverse">But Gods will be done.</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 Cold newes for me, for I had hope of France,</div>
<div class="dverse"><span class="lnum">35</span>
 Euen as I haue of fertill England.</div>

<div class="sd-entry">Enter Duke <i>Humphrey</i>.</div>

<div class="dverse1"><span class="sd-cn">Hum.</span>
 Pardon my liege, that I haue staid so long.</div>

<div class="dverse1"><span class="sd-cn">Suffol.</span>
 Nay, Gloster know, that thou art come too soone,</div>
<div class="dverse">Vnlesse thou proue more loyall then thou art,</div>
<div class="dverse">We do arrest thee on high treason here.</div>

<div class="dverse1"><span class="lnum">40</span>
 <span class="sd-cn">Humph.</span>
  Why Suffolkes Duke thou shalt not see me blush</div>
<div class="dverse">Nor change my countenance for thine arrest,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai042" id="lnum-dai042">♦</a>
 Whereof am I guiltie, who are my accusers?</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Tis thought my lord, your grace tooke bribes from France,</div>
<div class="dverse">And stopt the soldiers of their paie,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai045" id="lnum-dai045">45</a>
 By which his Maiestie hath lost all France.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dai046" id="lnum-dai046">♦</a>
 <span class="sd-cn">Humph.</span>
  Is it but thought so, and who are they that thinke so?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai047" id="lnum-dai047">♦</a>
 So God helpe me, as I haue watcht the night</div>
<div class="dverse">Euer intending good for England still,</div>
<div class="dverse">That penie that euer I tooke from France,</div>
<div class="dverse"><span class="lnum">50</span>
 Be brought against me at the iudgement day.</div>
<div class="dverse">I neuer robd the soldiers of their paie,</div>
<div class="dverse">Many a pound of mine owne propper cost</div>
<div class="dverse">Haue I sent ouer for the soldiers wants,</div>
<div class="dverse">Because I would not racke the needie Commons.</div>

<div class="dverse1"><span class="lnum">55</span>
 <span class="sd-cn">Car.</span>
  In your Protectorship you did deuise</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai056" id="lnum-dai056">♦</a>
 Strange torments for offendors, by which meanes</div>
<div class="dverse">England hath bene defamde by tyrannie.</div>

<div class="dverse1"><span class="sd-cn">Hum.</span>
 Why tis wel knowne that whilst I was protector</div>
<div class="dverse">Pitie was all the fault that was in me,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai060" id="lnum-dai060">60</a>
 A murtherer or foule felonous theefe,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai061" id="lnum-dai061">♦</a>
 That robs and murthers silly passengers,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai062" id="lnum-dai062">♦</a>
 I tortord aboue the rate of common law.</div>

<div class="dverse1"><span class="sd-cn">Suffolk.</span>
 Tush my Lord, these be things of no account,</div>
<div class="dverse">But greater matters are laid vnto your charge,</div>
<div class="dverse"><span class="lnum">65</span>
 I do arrest thee on high treason here,</div>
<div class="dverse">And commit thee to my good Lord Cardinall,</div>
<div class="dverse">Vntill such time as thou canst cleare thy selfe.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Good vnkle obey to his arrest,</div>
<div class="dverse"><i>I</i> haue no doubt but thou shalt cleare thy selfe,</div>
<div class="dverse"><span class="lnum">70</span>
 My conscience tels me thou art innocent.</div>

<div class="dverse1"><span class="sd-cn">Hump.</span>
 Ah gratious Henry these daies are dangerous,</div>
<div class="dverse">And would my death might end these miseries,</div>
<div class="dverse">And staie their moodes for good King Henries sake,</div>
<div class="dverse">But I am made the Prologue to their plaie,</div>
<div class="dverse"><span class="lnum">75</span>
 And thousands more must follow after me,</div>
<div class="dverse">That dreads not yet their liues destruction.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai077" id="lnum-dai077">♦</a>
 Suffolkes hatefull tongue blabs his harts malice,</div>
<div class="dverse">Bewfords firie eyes showes his enuious minde,</div>
<div class="dverse">Buckinghams proud lookes bewraies his cruel thoughts,</div>
<div class="dverse"><span class="lnum">80</span>
 And dogged Yorke that leuels at the Moone</div>
<div class="dverse">Whose ouerweening arme <i>I</i> haue held backe.</div>
<div class="dverse">All you haue ioynd to betraie me thus:</div>
<div class="dverse">And you my gratious Lady and soueraigne mistresse,</div>
<div class="dverse">Causelesse haue laid complaints vpon my head,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai085" id="lnum-dai085">85</a>
 I shall not want false witnesses inough,</div>
<div class="dverse">That so amongst you, you may haue my life.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai087" id="lnum-dai087">♦</a>
 The Prouerbe no doubt will be well performde,</div>
<div class="dverse">A staffe is quickly found to beate a dog.</div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 Doth he not twit our soueraigne Lady here,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai090" id="lnum-dai090">90</a>
 As if that she with ignomious wrong,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai091" id="lnum-dai091">♦</a>
 Had sobornde or hired some to sweare against his life.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dai092" id="lnum-dai092">♦</a>
 <span class="sd-cn">Queene.</span>
  I but I can giue the loser leaue to speake.</div>

<div class="dverse1"><span class="sd-cn">Humph.</span>
 Far truer spoke then ment, I loose indeed,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai094" id="lnum-dai094">♦</a>
 Beshrow the winners hearts, they plaie me false.</div>

<div class="dverse1"><span class="lnum">95</span>
 <span class="sd-cn">Buck.</span>
  Hele wrest the sence and keep vs here all day,</div>
<div class="dverse">My Lord of Winchester, see him sent away.</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 Who’s within there? Take in Duke Humphrey,</div>
<div class="dverse">And see him garded sure within my house.</div>

<div class="dverse1"><span class="sd-cn">Humph.</span>
 O! thus King Henry casts away his crouch,</div>
<div class="dverse"><span class="lnum">100</span>
 Before his legs can beare his bodie vp,</div>
<div class="dverse">And puts his watchfull shepheard from his side,</div>
<div class="dverse">Whilst wolues stand snarring who shall bite him first.</div>
<div class="dverse">Farwell my soueraigne, long maist thou enjoy,</div>
<div class="dverse">Thy fathers happie daies free from annoy. <span class="sd-verseend"><i>Exet Humphrey</i>, with the <i>Cardinals</i> men.</span></div>

<div class="dverse1"><span class="lnum">105</span>
 <span class="sd-cn">King.</span>
  My Lords what to your wisdoms shal seem best,</div>
<div class="dverse">Do and vndo as if our selfe were here.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 What wil your highnesse leaue the Parlament?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dai108" id="lnum-dai108">♦</a>
 <span class="sd-cn">King.</span>
  I Margaret. My heart is kild with griefe,</div>
<div class="dverse">Where I may sit and sigh in endlesse mone,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai110" id="lnum-dai110">110</a>
 For who’s a Traitor, Gloster he is none.
 <span class="sd-verseend"><i>Exet King, Salsbury</i>, and <i>Warwicke</i>.</span></div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 Then sit we downe againe my Lord Cardinall,</div>
<div class="dverse">Suffolke, Buckingham, Yorke, and Somerset.</div>
<div class="dverse">Let vs consult of proud Duke Humphries fall.</div>
<div class="dverse">In mine opinion it were good he dide,</div>
<div class="dverse"><span class="lnum">115</span>
 For safetie of our King and Common-wealth.</div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 And so thinke <i>I</i> Madame, for as you know,</div>
<div class="dverse">If our King Henry had shooke hands with death,</div>
<div class="dverse">Duke Humphrey then would looke to be our King:</div>
<div class="dverse">And it may be by pollicie he workes,</div>
<div class="dverse"><span class="lnum">120</span>
 To bring to passe the thing which now we doubt,</div>
<div class="dverse">The Foxe barkes not when he would steale the Lambe,</div>
<div class="dverse">But if we take him ere he do the deed,</div>
<div class="dverse">We should not question if that he should liue.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai124" id="lnum-dai124">♦</a>
 No. Let him die, in that he is a Foxe,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai125" id="lnum-dai125">125</a>
 Least that in liuing he offend vs more.</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 Then let him die before the Commons know,</div>
<div class="dverse">For feare that they do rise in Armes for him.</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 Then do it sodainly my Lords.</div>

<div class="dverse1"><span class="sd-cn">Suffol.</span>
 Let that be my Lord Cardinals charge &amp; mine.</div>

<div class="dverse1"><span class="lnum">130</span>
 <span class="sd-cn">Car.</span>
  Agreed, for hee’s already kept within my house.</div>

<div class="sd-entry">Enter a Messenger.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 How now sirrha, what newes?</div>

<div class="dverse1"><span class="sd-cn">Messen.</span>
 Madame I bring you newes from Ireland,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai133" id="lnum-dai133">♦</a>
 The wilde Onele my Lords, is vp in Armes,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai134" id="lnum-dai134">♦</a>
 With troupes of Irish Kernes that vncontrold,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai135" id="lnum-dai135">135</a>
 Doth plant themselues within the English pale.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 What redresse shal we haue for this my Lords?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dai137" id="lnum-dai137">♦</a>
 <span class="sd-cn">Yorke.</span>
  Twere very good that my Lord of Somerset</div>
<div class="dverse">That fortunate Champion were sent ouer,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai139" id="lnum-dai139">♦</a>
 And burnes and spoiles the Country as they goe.</div>
<div class="dverse"><span class="lnum">140</span>
 To keepe in awe the stubborne Irishmen,</div>
<div class="dverse">He did so much good when he was in France.</div>

<div class="dverse1"><span class="sd-cn">Somer.</span>
 Had Yorke bene there with all his far fetcht</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai143" id="lnum-dai143">♦</a>
 Pollices, he might haue lost as much as I.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dai144" id="lnum-dai144">♦</a>
 <span class="sd-cn">Yorke.</span>
  I, for Yorke would haue lost his life before</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai145" id="lnum-dai145">145</a>
 That France should haue reuolted from Englands rule.</div>

<div class="dverse1"><span class="sd-cn">Somer.</span>
 I so thou might’st, and yet haue gouernd worse then I.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dai147" id="lnum-dai147">♦</a>
 <span class="sd-cn">York.</span>
  What worse then nought, then a shame take all.</div>

<div class="dverse1"><span class="sd-cn">Somer.</span>
 Shame on thy selfe, that wisheth shame.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 Somerset forbeare, good Yorke be patient,</div>
<div class="dverse"><span class="lnum">150</span>
 And do thou take in hand to crosse the seas,</div>
<div class="dverse">With troupes of Armed men to quell the pride</div>
<div class="dverse">Of those ambitious Irish that rebell.</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 Well Madame sith your grace is so content,</div>
<div class="dverse">Let me haue some bands of chosen soldiers,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai155" id="lnum-dai155">155</a>
 And Yorke shall trie his fortune against those kernes.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dai156" id="lnum-dai156">♦</a>
 <span class="sd-cn">Queene.</span>
  Yorke thou shalt. My Lord of Buckingham,</div>
<div class="dverse">Let it be your charge to muster vp such souldiers</div>
<div class="dverse">As shall suffise him in these needfull warres.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dai159" id="lnum-dai159">♦</a>
 <span class="sd-cn">Buck.</span>
  Madame I will, and leauie such a band</div>
<div class="dverse"><span class="lnum">160</span>
 As soone shall ouercome those Irish Rebels,</div>
<div class="dverse">But Yorke, where shall those soldiers staie for thee?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dai162" id="lnum-dai162">♦</a>
 <span class="sd-cn">Yorke.</span>
  At Bristow, I wil expect them ten daies hence.</div>

<div class="dverse1"><span class="sd-cn">Buc.</span>
 Then thither shall they come, and so farewell. <span class="sd-verseend"><i>Exet Buckingham.</i></span></div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 Adieu my Lord of Buckingham.</div>

<div class="dverse1"><span class="lnum">165</span>
 <span class="sd-cn">Queene.</span>
  Suffolke remember what you haue to do.</div>
<div class="dverse">And you Lord Cardinall concerning Duke Humphrey,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai167" id="lnum-dai167">♦</a>
 Twere good that you did see to it in time,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai168" id="lnum-dai168">♦</a>
 Come let vs go, that it may be performde.
 <span class="sd-verseend"><i>Exet omnis, Manit Yorke.</i></span></div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Now York bethink thy self and rowse thee vp.</div>
<div class="dverse"><span class="lnum">170</span>
 Take time whilst it is offered thee so faire,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai171" id="lnum-dai171">♦</a>
 Least when thou wouldst, thou canst it not attaine,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai172" id="lnum-dai172">♦</a>
 Twas men I lackt, and now they giue them me,</div>
<div class="dverse">And now whilst I am busie in Ireland,</div>
<div class="dverse">I haue seduste a headstrong Kentishman,</div>
<div class="dverse"><span class="lnum">175</span>
 Iohn Cade of Ashford,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dai176" id="lnum-dai176">♦</a>
 Vnder the title of Iohn Mortemer,</div>
<div class="dverse">To raise commotion, and by that meanes</div>
<div class="dverse">I shall perceiue how the common people</div>
<div class="dverse">Do affect the claime and house of Yorke,</div>
<div class="dverse"><span class="lnum">180</span>
 Then if he haue successe in his affaires,</div>
<div class="dverse">From Ireland then comes Yorke againe,</div>
<div class="dverse">To reape the haruest which that coystrill sowed,</div>
<div class="dverse">Now if he should be taken and condemd,</div>
<div class="dverse">Heele nere confesse that I did set him on,</div>
<div class="dverse"><span class="lnum">185</span>
 And therefore ere I go ile send him word,</div>
<div class="dverse">To put in practise and to gather head.</div>
<div class="dverse">That so soone as I am gone he may begin</div>
<div class="dverse">To rise in Armes with troupes of country swaines,</div>
<div class="dverse">To helpe him to performe this enterprise.</div>
<div class="dverse"><span class="lnum">190</span>
 And then Duke Humphrey, he well made away,</div>
<div class="dverse">None then can stop the light to Englands Crowne,</div>
<div class="dverse">But Yorke can tame and headlong pull them downe. <span class="sd-verseend"><i>Exet Yorke.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> X.
<span class="dnavigatenf">daj</span></h3>

Then the Curtaines being drawne, Duke <i>Humphrey</i> is discouered
in his bed, and two men lying on his brest and smothering him in his bed.
And then enter the Duke of <i>Suffolke</i> to them.</div>

<div class="dverse1"><span class="sd-cn">Suffolk.</span>
 How now sirs, what haue you dispatcht him?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daj002" id="lnum-daj002">♦</a>
 <span class="sd-cn">One.</span>
  I my Lord, hees dead I warrant you.</div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 Then see the cloathes laid smooth about him still,</div>
<div class="dverse">That when the King comes, he may perceiue</div>
<div class="dverse"><span class="lnum">5</span>
 No other, but that he dide of his owne accord.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daj006" id="lnum-daj006">♦</a>
 <span class="sd-cn">2.</span>
  All things is hansome now my Lord.</div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 Then draw the Curtaines againe and get you gone,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj008" id="lnum-daj008">♦</a>
 And you shall haue your firme rewarde anon.
 <span class="sd-verseend"><i>Exet</i> murtherers.</span></div>

<div class="sd-entry">Then enter the King and Queene, the Duke of <i>Buckingham</i>, and the Duke of <i>Somerset</i>, and the Cardinall.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 My Lord of Suffolke go call our vnkle Gloster,</div>
<div class="dverse"><span class="lnum">10</span>
 Tell him this day we will that he do cleare himselfe.</div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 I will my Lord. <span class="sd-verseend"><i>Exet Suffolke.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daj012" id="lnum-daj012">♦</a>
 <span class="sd-cn">King.</span>
  And good my Lords proceed no further against our vnkle (Gloster,</div>
<div class="dverse">Then by iust proofe you can affirme,</div>
<div class="dverse">For as the sucking childe or harmlesse lambe,</div>
<div class="dverse"><span class="lnum">15</span>
 So is he innocent of treason to our state.</div>

<div class="sd-entry">Enter <i>Suffolke</i>.</div>

<div class="dverse">How now Suffolke, where’s our unkle?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daj017" id="lnum-daj017">♦</a>
 <span class="sd-cn">Suffolke.</span>
 Dead in his bed, my Lord Gloster is dead. <span class="sd-verseend">The King falles in a sound.</span></div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Ay-me, the King is dead: help, help, my Lords.</div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 Comfort my Lord, gratious Henry comfort.</div>

<div class="dverse1"><span class="sd-cn">Kin.</span>
 What doth my Lord of Suffolk bid me comfort?</div>
<div class="dverse">Came he euen now to sing a Rauens note,</div>
<div class="dverse">And thinkes he that the cherping of a Wren,</div>
<div class="dverse">By crying comfort through a hollow voice,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj024" id="lnum-daj024">♦</a>
 Can satisfie my griefes, or ease my heart:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj025" id="lnum-daj025">25</a>
 Thou balefull messenger out of my sight,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj026" id="lnum-daj026">♦</a>
 For euen in thine eye-bals murther sits,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj027" id="lnum-daj027">♦</a>
 Yet do not goe. Come Basaliske</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj028" id="lnum-daj028">♦</a>
 And kill the silly gazer with thy lookes.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 Why do you rate my Lord of Suffolke thus,</div>
<div class="dverse"><span class="lnum">30</span>
 As if that he had causde Duke Humphreys death?</div>
<div class="dverse">The Duke and I too, you know were enemies,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj032" id="lnum-daj032">♦</a>
 And you had best say that I did murther him.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Ah woe is me, for wretched Glosters death.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 Be woe for me more wretched then he was,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj035" id="lnum-daj035">35</a>
 What doest thou turne away and hide thy face?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj036" id="lnum-daj036">♦</a>
 I am no loathsome leoper looke on me,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj037" id="lnum-daj037">♦</a>
 Was I for this nigh wrackt vpon the sea,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj038" id="lnum-daj038">♦</a>
 And thrise by aukward winds driuen back from Englands bounds,</div>
<div class="dverse">What might it bode, but that well foretelling</div>
<div class="dverse"><span class="lnum">40</span>
 Winds, said, seeke not a scorpions neast.</div>

<div class="sd-entry">Enter the Earles of <i>Warwicke</i> and <i>Salisbury</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daj041" id="lnum-daj041">♦</a>
 <span class="sd-cn">War.</span>
  My Lord, the Commons like an angrie hiue of bees,</div>
<div class="dverse">Run vp and downe, caring not whom they sting,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj043" id="lnum-daj043">♦</a>
 For good Duke Humphreys death, whom they report</div>
<div class="dverse">To be murthered by Suffolke and the Cardinall here.</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">King.</span>
  That he is dead good Warwick, is too true,</div>
<div class="dverse">But how he died God knowes, not Henry.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Enter his priuie chamber my Lord and view the bodie.</div>
<div class="dverse">Good father staie you with the rude multitude, till I returne.</div>

<div class="dverse1"><span class="sd-cn">Salb.</span>
 I will sonne. <span class="sd-inline">  <i>Exet Salbury.</i></span>
 <span class="sd-verseend"><i>Warwicke</i> drawes the curtaines and showes Duke <i>Humphrey</i> in his bed.</span></div>

<div class="dverse1"><span class="lnum">50</span>
 <span class="sd-cn">King.</span>
  Ah vnkle Gloster, heauen receive thy soule.</div>
<div class="dverse">Farewell poore Henries ioy, now thou art gone.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Now by his soule that tooke our shape vpon him,</div>
<div class="dverse">To free vs from his fathers dreadfull curse,</div>
<div class="dverse">I am resolu’d that violent hands were laid,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj055" id="lnum-daj055">55</a>
 Vpon the life of this thrise famous Duke.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daj056" id="lnum-daj056">♦</a>
 <span class="sd-cn">Suffolk.</span>
  A dreadfull oth sworne with a solemne toong,</div>
<div class="dverse">What instance giues Lord Warwicke for these words?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Oft haue I seene a timely parted ghost,</div>
<div class="dverse">Of ashie semblance, pale and bloodlesse,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj060" id="lnum-daj060">60</a>
 But loe the blood is setled in his face,</div>
<div class="dverse">More better coloured then when he liu’d,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj062" id="lnum-daj062">♦</a>
 His well proportioned beard made rough and sterne,</div>
<div class="dverse">His fingers spred abroad as one that graspt for life,</div>
<div class="dverse">Yet was by strength surprisde, the least of these are probable,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj065" id="lnum-daj065">65</a>
 It cannot chuse but he was murthered.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 Suffolke and the Cardinall had him in charge,</div>
<div class="dverse">And they <i>I</i> trust sir, are no murtherers.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daj068" id="lnum-daj068">♦</a>
 <span class="sd-cn">War.</span>
  I, but twas well knowne they were not his friends,</div>
<div class="dverse">And tis well seene he found some enemies.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daj070" id="lnum-daj070">70</a>
 <span class="sd-cn">Card.</span>
  But haue you no greater proofes then these?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daj071" id="lnum-daj071">♦</a>
 <span class="sd-cn">War.</span>
  Who sees a hefer dead and bleeding fresh,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj072" id="lnum-daj072">♦</a>
 And sees hard-by a butcher with an axe,</div>
<div class="dverse">But will suspect twas he that made the slaughter?</div>
<div class="dverse">Who findes the partridge in the puttocks neast,</div>
<div class="dverse"><span class="lnum">75</span>
 But will imagine how the bird came there,</div>
<div class="dverse">Although the kyte soare with vnbloodie beake?</div>
<div class="dverse">Euen so suspitious is this Tragidie.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daj078" id="lnum-daj078">♦</a>
 <span class="sd-cn">Queene.</span>
  Are you the kyte Bewford, where’s your talants?</div>
<div class="dverse">Is Suffolke the butcher, where’s his knife?</div>

<div class="dverse1"><span class="lnum">80</span>
 <span class="sd-cn">Suffolke.</span>
  I weare no knife to slaughter sleeping men,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj081" id="lnum-daj081">♦</a>
 But heres a vengefull sword rusted with case,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj082" id="lnum-daj082">♦</a>
 That shall be scoured in his rankorous heart,</div>
<div class="dverse">That slanders me with murthers crimson badge,</div>
<div class="dverse">Say if thou dare, proud Lord of Warwickshire,</div>
<div class="dverse"><span class="lnum">85</span>
 That I am guiltie in Duke Humphreys death.
 <span class="sd-verseend"><i>Exet Cardinall.</i></span></div>

<div class="dverse1"><span class="sd-cn">War.</span>
 What dares not Warwicke, if false Suffolke dare him?</div>

<div class="dverse"><i>Queene</i>. He dares not calme his contumelious spirit,</div>
<div class="dverse">Nor cease to be an arrogant controwler,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj089" id="lnum-daj089">♦</a>
 Though Suffolk dare him twentie hundreth times.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daj090" id="lnum-daj090">90</a>
 <span class="sd-cn">War.</span>
  Madame be still, with reuerence may I say it,</div>
<div class="dverse">That euery word you speake in his defence,</div>
<div class="dverse">Is slaunder to your royall Maiestie.</div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 Blunt witted Lord, ignoble in thy words,</div>
<div class="dverse">If euer Lady wrongd her Lord so much,</div>
<div class="dverse"><span class="lnum">95</span>
 Thy mother tooke vnto her blamefull bed,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj096" id="lnum-daj096">♦</a>
 Some sterne vntutred churle, and noble stocke</div>
<div class="dverse">Was graft with crabtree slip, whose frute thou art,</div>
<div class="dverse">And neuer of the Neuels noble race.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 But that the guilt of murther bucklers thee,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj100" id="lnum-daj100">100</a>
 And I should rob the deaths man of his fee,</div>
<div class="dverse">Quitting thee thereby of ten thousand shames,</div>
<div class="dverse">And that my soueraignes presence makes me mute,</div>
<div class="dverse">I would false murtherous coward on thy knees</div>
<div class="dverse">Make thee craue pardon for thy passed speech,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj105" id="lnum-daj105">105</a>
 And say it was thy mother that thou meants,</div>
<div class="dverse">That thou thy selfe was borne in bastardie,</div>
<div class="dverse">And after all this fearefull homage done,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj108" id="lnum-daj108">♦</a>
 Giue thee thy hire and send thy soule to hell,</div>
<div class="dverse">Pernitious blood-sucker of sleeping men.</div>

<div class="dverse1"><span class="lnum">110</span>
 <span class="sd-cn">Suffol.</span>
  Thou shouldst be waking whilst I shead thy blood,</div>
<div class="dverse">If from this presence thou dare go with me.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Away euen now, or I will drag thee hence. <span class="sd-verseend">Warwicke puls him out.</span></div>

<div class="sd-entry"><i>Exet Warwicke</i> and <i>Suffolke</i>, and then all the
Commons within, cries, downe with <i>Suffolke</i>, downe with <i>Suffolk</i>.
<br>And then enter againe, the Duke of <i>Suffolke</i> and <i>Warwicke</i>, with
their weapons drawne.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Why how now Lords?</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 The Traitorous Warwicke with the men of Berry,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj115" id="lnum-daj115">115</a>
 Set all vpon me mightie soueraigne i</div>

<div class="sd-entry">The Commons againe cries, downe with <i>Suffolke</i>, downe with <i>Suffolke</i>. And then enter from them, the Earle of <i>Salbury</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daj116" id="lnum-daj116">♦</a>
 <span class="sd-cn">Salb.</span>
  My Lord, the Commons sends you word by me,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj117" id="lnum-daj117">♦</a>
 The vnlesse false Suffolke here be done to death,</div>
<div class="dverse">Or banished faire Englands Territories,</div>
<div class="dverse">That they will erre from your highnesse person,</div>
<div class="dverse"><span class="lnum">120</span>
 They say by him the good Duke Humphrey died,</div>
<div class="dverse">They say by him they feare the ruine of the realme.</div>
<div class="dverse">And therefore if you loue your subiects weale,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj123" id="lnum-daj123">♦</a>
 They wish you to banish him from foorth the land.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Indeed tis like the Commons rude vnpolisht hinds</div>
<div class="dverse"><span class="lnum">125</span>
 Would send such message to their soueraigne,</div>
<div class="dverse">But you my Lord were glad to be imployd,</div>
<div class="dverse">To trie how quaint an Orator you were,</div>
<div class="dverse">But all the honour Salsbury hath got,</div>
<div class="dverse">Is, that he was the Lord Embassador</div>
<div class="dverse"><span class="lnum">130</span>
 Sent from a sort of Tinkers to the King.</div>

<div class="sd-entry">The Commons cries, an answere from the King, my Lord of <i>Salsbury</i>.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Good Salsbury go backe againe to them,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj132" id="lnum-daj132">♦</a>
 Tell them we thanke them all for their louing care,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj133" id="lnum-daj133">♦</a>
 And had I not bene cited thus by their meanes,</div>
<div class="dverse">My selfe had done it. Therefore here I sweare,</div>
<div class="dverse"><span class="lnum">135</span>
 If Suffolke be found to breathe in any place,</div>
<div class="dverse">Where I haue rule, but three daies more, he dies. <span class="sd-verseend"><i>Exet Salisbury.</i></span></div>

<div class="dprose1"><span class="sd-cn">Queene.</span>
 Oh Henry, reuerse the doome of gentle Suffolkes banishment.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Vngentle Queene to call him gentle Suffolke,</div>
<div class="dverse">Speake not for him, for in England he shall not rest,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj140" id="lnum-daj140">140</a>
 If I say, I may relent, but if I sweare, it is erreuocable.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj141" id="lnum-daj141">♦</a>
 Come good Warwicke and go thou in with me,</div>
<div class="dverse">For I haue great matters to impart to thee. <span class="sd-verseend"><i>Exet</i> King and <i>Warwicke</i>, <i>Manet</i> Queene and <i>Suffolke</i>.</span></div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 Hell fire and vengeance go along with you,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj144" id="lnum-daj144">♦</a>
 Theres two of you, the diuell make the third.</div>
<div class="dverse"><span class="lnum">145</span>
 Fie womanish man, canst thou not curse thy enemies?</div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 A plague vpon them, wherefore should <i>I</i> curse them?</div>
<div class="dverse">Could curses kill as do the Mandrakes groanes,</div>
<div class="dverse">I would inuent as many bitter termes</div>
<div class="dverse">Deliuered strongly through my fixed teeth,</div>
<div class="dverse"><span class="lnum">150</span>
 With twise so many signes of deadly hate,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj151" id="lnum-daj151">♦</a>
 As leaue fast enuy in her loathsome caue,</div>
<div class="dverse">My toong should stumble in mine earnest words,</div>
<div class="dverse">Mine eyes should sparkle like the beaten flint,</div>
<div class="dverse">My haire be fixt on end, as one distraught,</div>
<div class="dverse"><span class="lnum">155</span>
 And euery ioynt should seeme to curse and ban,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj156" id="lnum-daj156">♦</a>
 And now me-thinks my burthened hart would breake,</div>
<div class="dverse">Should <i>I</i> not curse them. Poison be their drinke,</div>
<div class="dverse">Gall worse then gall, the daintiest thing they taste.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj159" id="lnum-daj159">♦</a>
 Their sweetest shade a groue of sypris trees,</div>
<div class="dverse"><span class="lnum">160</span>
 Their softest tuch as smart as lyzards stings.</div>
<div class="dverse">Their musicke frightfull, like the serpents hys.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj162" id="lnum-daj162">♦</a>
 And boding scrike-oules make the consort full.</div>
<div class="dverse">All the foule terrors in darke seated hell.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daj164" id="lnum-daj164">♦</a>
 <span class="sd-cn">Queene.</span>
  Inough sweete Suffolke, thou torments thy (selfe.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daj165" id="lnum-daj165">165</a>
 <span class="sd-cn">Suffolke.</span>
  You bad me ban, and will you bid me sease?</div>
<div class="dverse">Now by this ground that I am banisht from,</div>
<div class="dverse">Well could I curse away a winters night,</div>
<div class="dverse">And standing naked on a mountaine top,</div>
<div class="dverse">Where byting cold would neuer let grasse grow,</div>
<div class="dverse"><span class="lnum">170</span>
 And thinke it but a minute spent in sport.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 No more. Sweete Suffolke hie thee hence to <i>France</i>,</div>
<div class="dverse">Or liue where thou wilt within this worldes globe,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj173" id="lnum-daj173">♦</a>
 Ile haue an Irish that shall finde thee out,</div>
<div class="dverse">And long thou shalt not staie, but ile haue thee repelde,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj175" id="lnum-daj175">175</a>
 Or venture to be banished my selfe.</div>
<div class="dverse">Oh let this kisse be printed in thy hand,</div>
<div class="dverse">That when thou seest it, thou maist thinke on me.</div>
<div class="dverse">Away, I say, that I may feele my griefe,</div>
<div class="dverse">For it is nothing whilst thou standest here.</div>

<div class="dverse1"><span class="lnum">180</span>
 <span class="sd-cn">Suffolke.</span>  Thus is poore <i>Suffolke</i> ten times banished,</div>
<div class="dverse">Once by the King, but three times thrise by thee.</div>

<div class="sd-entry">Enter <i>Vawse</i>.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 How now, whither goes Vawse so fast?</div>

<div class="dverse1"><span class="sd-cn">Vawse.</span>
 To signifie vnto his Maiestie,</div>
<div class="dverse">That Cardinall Bewford is at point of death,</div>
<div class="dverse"><span class="lnum">185</span>
 Sometimes he raues and cries as he were madde,</div>
<div class="dverse">Sometimes he cals vpon Duke Humphries Ghost,</div>
<div class="dverse">And whispers to his pillow as to him,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj188" id="lnum-daj188">♦</a>
 And sometime he calles to speake vnto the King,</div>
<div class="dverse">And I am going to certifie vnto his grace,</div>
<div class="dverse"><span class="lnum">190</span>
 That euen now he cald aloude for him.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 Go then good Vawse and certifie the King <span class="sd-verseend"><i>Exet Vawse.</i></span></div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj192" id="lnum-daj192">♦</a>
 Oh what is worldly pompe, all men must die,</div>
<div class="dverse">And woe am I for Bewfords heauie ende.</div>
<div class="dverse">But why mourne I for him, whilst thou art here?</div>
<div class="dverse"><span class="lnum">195</span>
 Sweete Suffolke hie thee hence to France,</div>
<div class="dverse">For if the King do come, thou sure must die.</div>

<div class="dverse1"><span class="sd-cn">Suff.</span>
 And if I go I cannot liue: but here to die,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj198" id="lnum-daj198">♦</a>
 What were it else, but like a pleasant slumber</div>
<div class="dverse">In thy lap?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj200" id="lnum-daj200">200</a>
 Here could I, could I, breath my soule into the aire,</div>
<div class="dverse">As milde and gentle as the new borne babe,</div>
<div class="dverse">That dies with mothers dugge betweene his lips,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daj203" id="lnum-daj203">♦</a>
 Where from thy sight I should be raging madde,</div>
<div class="dverse">And call for thee to close mine eyes,</div>
<div class="dverse"><span class="lnum">205</span>
 Or with thy lips to stop my dying soule,</div>
<div class="dverse">That <i>I</i> might breathe it so into thy bodie,</div>
<div class="dverse">And then it liu’d in sweete Elyziam,</div>
<div class="dverse">By thee to die, were but to die in ieast,</div>
<div class="dverse">From thee to die, were torment more then death,</div>
<div class="dverse"><span class="lnum">210</span>
 O let me staie, befall, what may befall.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Oh mightst thou staie with safetie of thy life,</div>
<div class="dverse">Then shouldst thou staie, but heauens deny it,</div>
<div class="dverse">And therefore go, but hope ere longe to be repelde.</div>

<div class="dverse1"><span class="sd-cn">Suff.</span>
 <i>I</i> goe.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 And take my heart with thee. <span class="lnum">215</span>
 <span class="sd-verseend">She kisseth him.</span></div>

<div class="dverse1"><span class="sd-cn">Suff.</span>
A iewell lockt into the wofulst caske,</div>
<div class="dverse">That euer yet containde a thing of woorth,</div>
<div class="dverse">Thus like a splitted barke so sunder we.</div>
<div class="dverse"><span class="lnum">220</span>
 This way fall I to death.
 <span class="sd-verseend"><i>Exet Suffolke.</i></span></div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 This way for me.
 <span class="sd-verseend"><i>Exet Queene.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XI.
<span class="dnavigatenf">dak</span></h3>

Enter King and <i>Salsbury</i>, and then the Curtaines be drawne, and the
Cardinall is discouered in his bed, rauing and staring as if he were
madde.</div>

<div class="dverse1"><span class="sd-cn">Car.</span>
 Oh death, if thou wilt let me liue but one whole yeare,</div>
<div class="dverse">Ile giue thee as much gold as will purchase such another Iland.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Oh see my Lord of Salsbury how he is troubled,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dak004" id="lnum-dak004">♦</a>
 Lord Cardinall, remember Christ must saue thy soule.</div>

<div class="dverse1"><span class="lnum">5</span>
 <span class="sd-cn">Car.</span>
  Why died he not in his bed?</div>
<div class="dverse">What would you haue me to do then?</div>
<div class="dverse">Can I make men liue whether they will or no?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dak008" id="lnum-dak008">♦</a>
 Sirra, go fetch me the strong poison which the Pothicary sent me.</div>
<div class="dverse">Oh see where Duke Humphreys ghoast doth stand,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dak010" id="lnum-dak010">10</a>
 And stares me in the face. Looke, looke, coame downe his haire,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dak011" id="lnum-dak011">♦</a>
 So now hees gone againe: Oh, oh, oh.</div>

<div class="dverse1"><span class="sd-cn">Sal.</span>
 See how the panges of death doth gripe his heart.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Lord Cardinall, if thou diest assured of heauenly blisse,</div>
<div class="dverse">Hold vp thy hand and make some signe to vs. <span class="sd-verseend">The Cardinall dies.</span></div>

<div class="dverse"><span class="lnum">15</span>
 Oh see he dies, and makes no signe at all.</div>
<div class="dverse">Oh God forgiue his soule.</div>

<div class="dverse1"><span class="sd-cn">Salb.</span>
 So bad an ende did neuer none behold,</div>
<div class="dverse">But as his death, so was his life in all.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Forbeare to iudge, good Salsbury forbeare,</div>
<div class="dverse"><span class="lnum">20</span>
 For God will iudge vs all.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dak021" id="lnum-dak021">♦</a>
 Go take him hence, and see his funerals be performde. <span class="sd-verseend"><i>Exet omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XII.
<span class="dnavigatenf">dal</span></h3>

Alarmes within, and the chambers be discharged, like as it were a fight at sea. And then enter the Captaine of the ship and the Maister, and the Maisters Mate, &amp; the Duke of Suffolke disguised, and others with him, and Water Whickmore.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dal001" id="lnum-dal001">♦</a>
 <span class="sd-cn">Cap.</span>
  Bring forward these prisoners that scorn’d to yeeld,</div>
<div class="dverse">Vnlade their goods with speed and sincke their ship,</div>
<div class="dverse">Here Maister, this prisoner I giue to you.</div>
<div class="dverse">This other, the Maisters Mate shall haue,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dal005" id="lnum-dal005">5</a>
 And Water Whickmore thou shalt haue this man,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dal006" id="lnum-dal006">♦</a>
 And let them paie their ransomes ere they passe.</div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 Water!      He starteth.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dal008" id="lnum-dal008">♦</a>
 <span class="sd-cn">Water.</span>
  How now, what doest thou feare me?</div>
<div class="dverse">Thou shalt haue better cause anon.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 It is thy name affrights me, not thy selfe.</div>
<div class="dverse">I do remember well, a cunning Wyssard told me,</div>
<div class="dverse">That by Water I should die:</div>
<div class="dverse">Yet let not that make thee bloudie minded.</div>
<div class="dverse">Thy name being rightly sounded,</div>
<div class="dverse"><span class="lnum">15</span>
 Is Gualter, not Water.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dal016" id="lnum-dal016">♦</a>
 <span class="sd-cn">Water.</span>
  Gualter or Water, als one to me,</div>
<div class="dverse">I am the man must bring thee to thy death.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 I am a Gentleman looke on my Ring,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dal019" id="lnum-dal019">♦</a>
 Ransome me at what thou wilt, it shalbe paid.</div>

<div class="dverse1"><span class="lnum">20</span>
 <span class="sd-cn">Water.</span>
  I lost mine eye in boording of the ship,</div>
<div class="dverse">And therefore ere I marchantlike sell blood for gold,</div>
<div class="dverse">Then cast me headlong downe into the sea.</div>

<div class="dverse1"><span class="sd-cn">2. Priso.</span>
 But what shall our ransomes be?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dal024" id="lnum-dal024">♦</a>
 <span class="sd-cn">Mai.</span>
  A hundreth pounds a piece, either paie that or die.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">2. Priso.</span>
  Then saue our liues, it shall be paid.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dal026" id="lnum-dal026">♦</a>
 <span class="sd-cn">Water.</span>
  Come sirrha, thy life shall be the ransome</div>
<div class="dverse">I will haue.</div>

<div class="dverse1"><span class="sd-cn">Suff.</span>
 Staie villaine, thy prisoner is a Prince,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dal029" id="lnum-dal029">♦</a>
 The Duke of Suffolke, William de la Poull.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dal030" id="lnum-dal030">30</a>
 <span class="sd-cn">Cap.</span>
  The Duke of Suffolke folded vp in rags.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dal031" id="lnum-dal031">♦</a>
 <span class="sd-cn">Suf.</span>
  I sir, but these rags are no part of the Duke,</div>
<div class="dverse">Ioue sometime went disguisde, and why not I?</div>

<div class="dverse1"><span class="sd-cn">Cap.</span>
 I but Ioue was neuer slaine as thou shalt be.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Base Iadie groome, King Henries blood</div>
<div class="dverse"><span class="lnum">35</span>
 The honourable blood of Lancaster,</div>
<div class="dverse">Cannot be shead by such a lowly swaine,</div>
<div class="dverse">I am sent Ambassador for the Queene to France,</div>
<div class="dverse">I charge thee waffe me crosse the channell safe.</div>

<div class="dverse1"><span class="sd-cn">Cap.</span>
 Ile waffe thee to thy death, go Water take him hence,</div>
<div class="dverse"><span class="lnum">40</span>
 And on our long boates side, chop off his head.</div>

<div class="dverse1"><span class="sd-cn">Suf.</span>
 Thou darste not for thine owne.</div>

<div class="dverse1"><span class="sd-cn">Cap.</span>
 Yes Poull.</div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 Poull.</div>

<div class="dverse1"><span class="sd-cn">Cap.</span>
 I Poull, puddle, kennell, sinke and durt,</div>
<div class="dverse"><span class="lnum">45</span>
 Ile stop that yawning mouth of thine,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dal046" id="lnum-dal046">♦</a>
 Those lips of thine that so oft haue kist the</div>
<div class="dverse">Queene, shall sweepe the ground, and thou that</div>
<div class="dverse">Smildste at good Duke Humphreys death,</div>
<div class="dverse">Shalt liue no longer to infect the earth.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dal050" id="lnum-dal050">50</a>
 <span class="sd-cn">Suffolke.</span>
  This villain being but Captain of a Pinnais,</div>
<div class="dverse">Threatens more plagues then mightie Abradas,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dal052" id="lnum-dal052">♦</a>
 The great Masadonian Pyrate,</div>
<div class="dverse">Thy words addes fury and not remorse in me.</div>

<div class="dverse1"><span class="sd-cn">Cap.</span>
 I but my deeds shall staie thy fury soone.</div>

<div class="dverse1"><span class="lnum">55</span>
 <span class="sd-cn">Suffolke.</span>
  Hast not thou waited at my Trencher,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dal056" id="lnum-dal056">♦</a>
 When we haue feasted with Queene Margret?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dal057" id="lnum-dal057">♦</a>
 Hast not thou kist thy hand and held my stirrope?</div>
<div class="dverse">And barehead plodded by my footecloth Mule,</div>
<div class="dverse">And thought thee happie when I smilde on thee?</div>
<div class="dverse"><span class="lnum">60</span>
 This hand hath writ in thy defence,</div>
<div class="dverse">Then shall I charme thee, hold thy lauish toong.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dal062" id="lnum-dal062">♦</a>
 <span class="sd-cn">Cap.</span>
  Away with him, Water, I say, and off with his hed.</div>

<div class="dverse1"><span class="sd-cn">1. Priso.</span>
 Good my Lord, intreat him mildly for your life.</div>

<div class="dverse1"><span class="sd-cn">Suffolke.</span>
 First let this necke stoupe to the axes edge,</div>
<div class="dverse"><span class="lnum">65</span>
 Before this knee do bow to any,</div>
<div class="dverse">Saue to the God of heauen and to my King:</div>
<div class="dverse">Suffolkes imperiall toong cannot pleade</div>
<div class="dverse">To such a Iadie groome.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dal069" id="lnum-dal069">♦</a>
 <span class="sd-cn">Water.</span>
  Come, come, why do we let him speake,</div>
<div class="dverse"><span class="lnum">70</span>
 I long to haue his head for raunsome of mine eye.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dal071" id="lnum-dal071">♦</a>
 <span class="sd-cn">Suffolke.</span>
  A Swordar and bandeto slaue,</div>
<div class="dverse">Murthered sweete Tully.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dal073" id="lnum-dal073">♦</a>
 Brutus bastard-hand stabde Iulius Cæsar,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dal074" id="lnum-dal074">♦</a>
 And Suffolke dies by Pyrates on the seas. <span class="sd-verseend"><i>Exet Suffolke</i> and <i>Water</i>.</span></div>

<div class="dverse1"><span class="lnum">75</span>
 <span class="sd-cn">Cap.</span>
  Off with his head, and send it to the Queene,</div>
<div class="dverse">And ransomelesse this prisoner shall go free,</div>
<div class="dverse">To see it safe deliuered vnto her.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dal078" id="lnum-dal078">♦</a>
 Come lets goe. <span class="sd-verseend"><i>Exet omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XIII.
<span class="dnavigatenf">dam</span></h3>

Enter two of the Rebels with long staues.</div>

<div class="dprose1"><span class="sd-cn">George.</span>
 Come away Nick, and put a long staffe in thy pike, and prouide thy selfe, for I Can tell thee, they haue been vp this two daies. </div>

<div class="dverse1"><span class="sd-cn">Nicke.</span>
 Then they had more need to go to bed now,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dam005" id="lnum-dam005">5</a>
 But sirrha George whats the matter?</div>

<div class="dverse1"><span class="sd-cn">George.</span>
 Why sirrha, Iack Cade the Diar of Ashford here,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dam007" id="lnum-dam007">♦</a>
 He meanes to turne this land, and set a new nap on it.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dam008" id="lnum-dam008">♦</a>
 <span class="sd-cn">Nick.</span>
  I marry he had need so, for tis growne threedbare,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dam009" id="lnum-dam009">♦</a>
 Twas neuer merry world with vs, since these gentle men came vp.</div>

<div class="dprose1"><span class="lnum">10</span>
 <span class="sd-cn">George.</span>
 I warrant thee, thou shalt neuer see a Lord weare a leather aperne now a-daies.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dam012" id="lnum-dam012">♦</a>
 <span class="sd-cn">Nick.</span>
 But sirrha, who comes more beside Iacke Cade?</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dam013" id="lnum-dam013">♦</a>
 <span class="sd-cn">George.</span>
 Why theres Dicke the Butcher, and Robin the Sadler, and Will that came a wooing to our Nan last Sunday, and Harry and <span class="lnum">15</span>
 Tom, and Gregory that should haue your Parnill, and a great sort more is come from Rochester, and from Maydstone, and Canterbury, <a class="lnum pginternal" href="#lnote-dam017" id="lnum-dam017">♦</a>
 and all the Townes here abouts, and we must all be Lords or squires, assoone as Iack Cade is King.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dam019" id="lnum-dam019">♦</a>
 <span class="sd-cn">Nicke.</span>
 Harke, harke, I here the Drum, they be comming.</div>

<div class="sd-entry"> Enter <i>Iacke Cade</i>, <i>Dicke Butcher</i>, <i>Robin</i>, <i>Will</i>, <i>Tom</i>, <i>Harry</i> and the rest, with long staues.</div>

<div class="dverse1"><span class="lnum">20</span>
 <span class="sd-cn">Cade.</span>
  Proclaime silence.</div>

<div class="dverse1"><span class="sd-cn">All.</span>
 Silence.</div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 I Iohn Cade so named for my valiancie.</div>

<div class="dverse1"><span class="sd-cn">Dicke.</span>
 Or rather for stealing of a Cade of Sprats.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dam024" id="lnum-dam024">♦</a>
 <span class="sd-cn">Cade.</span>
  My father was a Mortemer.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dam025" id="lnum-dam025">25</a>
 <span class="sd-cn">Nicke.</span>
  He was an honest man and a good Brick-laier.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dam026" id="lnum-dam026">♦</a>
 <span class="sd-cn">Cade.</span>
  My mother came of the Brases.</div>

<div class="dverse1"><span class="sd-cn">Will.</span>
 She was a Pedlers daughter indeed, and sold many</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dam027" id="lnum-dam027">♦</a>
 lases.</div>

<div class="dverse1"><span class="sd-cn">Robin.</span>
 And now being not able to occupie her furd packe,</div>
<div class="dverse">She washeth buckes vp and down the country.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dam030" id="lnum-dam030">30</a>
 <span class="sd-cn">Cade.</span>
  Therefore I am honourably borne.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dam031" id="lnum-dam031">♦</a>
 <span class="sd-cn">Harry.</span>
  I for the field is honourable, for he was borne</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dam032" id="lnum-dam032">♦</a>
 Vnder a hedge, for his father had no house but the Cage.</div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 I am able to endure much.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dam034" id="lnum-dam034">♦</a>
 <span class="sd-cn">George.</span>
  Thats true, I know he can endure any thing,</div>
<div class="dverse"><span class="lnum">35</span>
 For I haue seen him whipt two market daies togither.</div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 I feare neither sword nor fire.</div>

<div class="dverse1"><span class="sd-cn">Will.</span>
 He need not feare the sword, for his coate is of proofe.</div>

<div class="dverse1"><span class="sd-cn">Dicke.</span>
 But mee thinkes he should feare the fire, being so often</div>
<div class="dverse">burnt in the hand, for stealing of sheepe.</div>

<div class="dprose1"><span class="lnum">40</span>
 <span class="sd-cn">Cade.</span>
 Therefore be braue, for your Captain is braue, and vowes reformation: you shall haue seuen half-penny loaues for a penny, <a class="lnum pginternal" href="#lnote-dam042" id="lnum-dam042">♦</a>
 and the three hoopt pot, shall haue ten hoopes, and it shall be felony <a class="lnum pginternal" href="#lnote-dam043" id="lnum-dam043">♦</a>
 to drinke small beere, and if I be king, as king I will be.</div>

<div class="dprose1"><span class="sd-cn">All.</span>
 God saue your maiestie.</div>

<div class="dprose1"><span class="lnum">45</span>
 <span class="sd-cn">Cade.</span>
 I thanke you good people, you shall all eate and drinke of <a class="lnum pginternal" href="#lnote-dam046" id="lnum-dam046">♦</a>
 my score, and go all in my liuerie, and weele haue no writing, but <a class="lnum pginternal" href="#lnote-dam047" id="lnum-dam047">♦</a>
 the score &amp; the Tally, and there shalbe no lawes but such as comes from my mouth.</div>

<div class="dprose1"><span class="sd-cn">Dicke.</span>
 We shall haue sore lawes then, for he was thrust into the <span class="lnum">50</span> mouth the other day.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dam051" id="lnum-dam051">♦</a>
 <span class="sd-cn">George.</span>
 I and stinking law too, for his breath stinks so, that one cannot abide it.</div>

<div class="sd-entry">Enter <i>Will</i> with the Clarke of <i>Chattam</i>.</div>

<div class="dprose1"><span class="sd-cn">Will.</span>
 Oh Captaine a pryze.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dam054" id="lnum-dam054">♦</a>
 <span class="sd-cn">Cade.</span>
 Whose that Will?</div>

<div class="dprose1"><span class="lnum">55</span>
 <span class="sd-cn">Will.</span>
 The Clarke of <i>Chattam,</i> he can write and reade and cast account, I tooke him setting of boyes coppies, and hee has a booke in his pocket with red letters.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dam058" id="lnum-dam058">♦</a>
 <span class="sd-cn">Cade.</span>
  Sonnes, hees a coniurer bring him hither.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dam059" id="lnum-dam059">♦</a>
 Now sir, whats your name?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dam060" id="lnum-dam060">60</a>
 <span class="sd-cn">Clarke.</span>
  Emanuell sir, and it shall please you.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dam061" id="lnum-dam061">♦</a>
 <span class="sd-cn">Dicke.</span>
  It will go hard with you, I can tell you,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dam062" id="lnum-dam062">♦</a>
 For they vse to write that oth top of letters.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dam063" id="lnum-dam063">♦</a>
 <span class="sd-cn">Cade.</span>
  And what do you vse to write your name?</div>
<div class="dverse">Or do you as auncient forefathers haue done,</div>
<div class="dverse"><span class="lnum">65</span>
 Vse the score and the Tally?</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dam066" id="lnum-dam066">♦</a>
 <span class="sd-cn">Clarke.</span>
 Nay, true sir, I praise God I haue been so well brought vp, that I can write mine owne name.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dam068" id="lnum-dam068">♦</a>
 <span class="sd-cn">Cade.</span>
 Oh hes confest, go hang him with his penny-inckhorne about his necke. <span class="sd-proseend"><i>Exet</i>
 one with the Clarke.</span></div>

<div class="sd-entry">Enter <i>Tom</i>.</div>

<div class="dprose1"><span class="lnum">70</span>
 <span class="sd-cn">Tom.</span>
 Captaine. Newes, newes, sir Humphrey Stafford and his
 <a class="lnum pginternal" href="#lnote-dam071" id="lnum-dam071">♦</a>
 brother are comming with the kings power, and mean to kill vs all.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dam072" id="lnum-dam072">♦</a>
 <span class="sd-cn">Cade.</span>
 Let them come, hees but a knight is he?</div>

<div class="dprose1"><span class="sd-cn">Tom.</span>
 No, no, hees but a knight. </div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 Why then to equall him, ile make my selfe knight.</div>
<div class="dverse"><span class="lnum">75</span>
 Kneele downe Iohn Mortemer,</div>
<div class="dverse">Rise vp sir Iohn Mortemer.</div>
<div class="dverse">Is there any more of them that be Knights?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dam078" id="lnum-dam078">♦</a>
 <span class="sd-cn">Tom.</span>
 I his brother. <span class="sd-verseend">He Knights <i>Dicke Butcher.</i></span></div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 Then kneele downe Dicke Butcher,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dam080" id="lnum-dam080">80</a>
 Rise vp sir Dicke Butcher. <span class="sd-verseend">Now sound vp the Drumme.</span></div>

<div class="sd-entry">Enter sir <i>Humphrey Stafford</i> and his brother, with Drumme and souldiers.</div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 As for these silken coated slaues I passe not a pinne,</div>
<div class="dverse">Tis to you good people that I speake.</div>

<div class="dverse1"><span class="sd-cn">Stafford.</span>
 Why country-men, what meane you thus in troopes,</div>
<div class="dverse">To follow this rebellious Traitor Cade?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dam085" id="lnum-dam085">85</a>
 Why his father was but a Brick-laier.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dam086" id="lnum-dam086">♦</a>
 <span class="sd-cn">Cade.</span>
  Well, and Adam was a Gardner, what then?</div>
<div class="dverse">But I come of the Mortemers.</div>

<div class="dverse1"><span class="sd-cn">Stafford.</span>
 I, the Duke of Yorke hath taught you that.</div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 The Duke of York, nay, I learnt it my selfe,</div>
<div class="dverse"><span class="lnum">90</span>
 For looke you, Roger Mortemer the Earle of March,</div>
<div class="dverse">Married the Duke of Clarence daughter.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dam092" id="lnum-dam092">♦</a>
 <span class="sd-cn">Stafford.</span>
  Well, thats true: But what then?</div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 And by her he had two children at a birth.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dam094" id="lnum-dam094">♦</a>
 <span class="sd-cn">Stafford.</span>
  Thats false.</div>

<div class="dverse1"><span class="lnum">95</span>
 <span class="sd-cn">Cade.</span>
  I, but I say, tis true.</div>

<div class="dverse1"><span class="sd-cn">All.</span>
 Why then tis true.</div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 And one of them was stolne away by a begger-woman,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dam098" id="lnum-dam098">♦</a>
 And that was my father, and I am his sonne,</div>
<div class="dverse">Deny it and you can.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dam100" id="lnum-dam100">100</a>
 <span class="sd-cn">Nicke.</span>
  Nay looke you, I know twas true,</div>
<div class="dverse">For his father built a chimney in my fathers house,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dam102" id="lnum-dam102">♦</a>
 And the brickes are aliue at this day to testifie.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
 But doest thou heare Stafford, tell the King, that for his fathers sake, in whose time boyes plaide at spanne-counter with <span class="lnum">105</span>
 Frenche Crownes, I am content that hee shall be King as long <a class="lnum pginternal" href="#lnote-dam106" id="lnum-dam106">♦</a>
 as he liues. Marry alwaies prouided, ile be Protector ouer him.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dam107" id="lnum-dam107">♦</a>
 <span class="sd-cn">Stafford.</span>
 O monstrous simplicitie.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dam108" id="lnum-dam108">♦</a>
 <span class="sd-cn">Cade.</span>
 And tell him, weele haue the Lorde Sayes head, and the Duke of Somersets, for deliuering vp the Dukedomes of Anioy <span class="lnum">110</span>
 and Mayne, and selling the Townes in France, by which meanes <a class="lnum pginternal" href="#lnote-dam111" id="lnum-dam111">♦</a>
 England hath bene maimde euer since, and gone as it were with a <a class="lnum pginternal" href="#lnote-dam112" id="lnum-dam112">♦</a>
 crouch, but that my puissance held it vp. And besides, they can speake French, and therefore they are traitors.</div>

<div class="dprose1"><span class="sd-cn">Stafford.</span>
 As how I prethie?</div>

<div class="dprose1"><span class="lnum">115</span>
 <span class="sd-cn">Cade.</span>
 Why the French men are our enemies be they not? And then can hee that speakes with the tongue of an enemy be a good subject?</div>

<div class="dprose">Answere me to that.</div>

<div class="dprose1"><span class="sd-cn">Stafford.</span>
 Well sirrha, wilt thou yeeld thy selfe vnto the Kings <a class="lnum pginternal" href="#lnote-dam120" id="lnum-dam120">120</a>
 mercy, and he will pardon thee and these, their outrages and rebellious deeds?</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
 Nay, bid the King come to me and he will, and then ile pardon him, or otherwaies ile haue his Crowne tell him, ere it be long.</div>

<div class="dverse1"><span class="lnum">125</span>
 <span class="sd-cn">Stafford.</span>
  Go Herald, proclaime in all the Kings Townes,</div>
<div class="dverse">That those that will forsake the Rebell Cade,</div>
<div class="dverse">Shall haue free pardon from his Maiestie. <span class="sd-verseend"><i>Exet Stafford</i> and his men.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dam128" id="lnum-dam128">♦</a>
 <span class="sd-cn">Cade.</span>
 Come sirs, saint George for vs and Kent. <span class="sd-verseend"><i>Exet omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XIV
<span class="dnavigatenf">dan</span></h3>

Alarums to the battaile, and sir <i>Humphrey Stafford</i> and his brother is slaine. Then enter <i>Iacke Cade</i> againe and the rest.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dan001" id="lnum-dan001">♦</a>
 <span class="sd-cn">Cade.</span>
 Sir Dicke Butcher, thou hast fought to day most valianly, And knockt them down as if thou hadst bin in thy slaughter house. And thus I will reward thee. The Lent shall be as long againe <a class="lnum pginternal" href="#lnote-dan004" id="lnum-dan004">♦</a>
 as it was. Thou shalt haue licence to kil for foure score &amp; one a week. <a class="lnum pginternal" href="#lnote-dan005" id="lnum-dan005">5</a>
 Drumme strike vp, for now weele march to London, for to morrow <a class="lnum pginternal" href="#lnote-dan006" id="lnum-dan006">♦</a>
 I meane to sit in the Kings seate at Westminster. <span class="sd-proseend"><i>Exet omnes.</i></span><div class="clearboth"></div></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span>
XV. <span class="dnavigatenf">dao</span></h3>

Enter the King reading of a Letter, and the Queene, with the Duke of
<i>Suffolkes</i> head, and the Lord <i>Say</i>, with others.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Sir <i>Humphrey Stafford</i> and his brother is slaine,</div>
<div class="dverse">And the Rebels march amaine to London,</div>
<div class="dverse">Go back to them, and tell them thus from me,</div>
<div class="dverse">Ile come and parley with their generall.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dao005" id="lnum-dao005">5</a>
 <span class="sd-cn">Reade.</span>
  Yet staie, ile reade the Letter one againe.</div>
<div class="dverse">Lord Say, Iacke Cade hath solemnely vowde to haue thy head.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dao007" id="lnum-dao007">♦</a>
 <span class="sd-cn">Say.</span>
  I, but I hope your highnesse shall haue his.</div>

<div class="dprose1"><span class="sd-cn">King.</span>
 How now Madam, still lamenting and mourning for Suffolkes <a class="lnum pginternal" href="#lnote-dao009" id="lnum-dao009">♦</a>
 death, I feare my loue, if I had bene dead, thou wouldst not <span class="lnum">10</span>
 haue mournde so much for me.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dao011" id="lnum-dao011">♦</a>
 <span class="sd-cn">Queene.</span>
  No my loue, I should not mourne, but die for thee.</div>

<div class="sd-entry">Enter a Messenger.</div>

<div class="dverse1"><span class="sd-cn">Messen.</span>
 Oh flie my Lord, the Rebels are entered</div>
<div class="dverse">Southwarke, and haue almost wonne the Bridge,</div>
<div class="dverse">Calling your grace an vsurper,</div>
<div class="dverse"><span class="lnum">15</span>
 And that monstrous Rebell Cade, hath sworne</div>
<div class="dverse">To Crowne himselfe King in Westminster,</div>
<div class="dverse">Therefore flie my Lord, and poste to Killingworth.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Go bid Buckingham and Clifford, gather</div>
<div class="dverse">An Army vp, and meete with the Rebels.</div>
<div class="dverse"><span class="lnum">20</span>
 Come Madame, let vs haste to Killingworth.</div>
<div class="dverse">Come on Lord Say, go thou along with vs,</div>
<div class="dverse">For feare the Rebell Cade do finde thee out.</div>

<div class="dverse1"><span class="sd-cn">Say.</span>
 My innocence my Lord shall pleade for me.</div>
<div class="dverse">And therfore with your highnesse leaue, ile staie behind.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">King.</span>
  Euen as thou wilt my Lord Say.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dao026" id="lnum-dao026">♦</a>
 Come Madame, let vs go.
 <span class="sd-verseend"><i>Exet omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XVI.
<span class="dnavigatenf">dap</span></h3>

Enter the Lord <i>Skayles</i> vpon the Tower walles walking.</div>

<div class="sd-schg">Enter three or foure Citizens below.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dap001" id="lnum-dap001">♦</a>
 <span class="sd-cn">Lord Scayles.</span>
  How now, is Iacke Cade slaine?</div>

<div class="dverse1"><span class="sd-cn">1. Citizen.</span>
 No my Lord, nor likely to be slaine,</div>
<div class="dverse">For they haue wonne the bridge,</div>
<div class="dverse">Killing all those that withstand them.</div>
<div class="dverse"><span class="lnum">5</span>
 The Lord Mayor craueth ayde of your honor from the Tower,</div>
<div class="dverse">To defend the Citie from the Rebels.</div>

<div class="dverse1"><span class="sd-cn">Lord Scayles.</span>
 Such aide as I can spare, you shall command,</div>
<div class="dverse">But I am troubled here with them my selfe,</div>
<div class="dverse">The Rebels haue attempted to win the Tower,</div>
<div class="dverse"><span class="lnum">10</span>
 But get you to Smythfield and gather head,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dap011" id="lnum-dap011">♦</a>
 And thither I will send you Mathew Goffe,</div>
<div class="dverse">Fight for your King, your Country, and your liues,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dap013" id="lnum-dap013">♦</a>
 And so farewell, for I must hence againe. <span class="sd-verseend"><i>Exet omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XVII.
<span class="dnavigatenf">daq</span></h3>

Enter <i>Iacke Cade</i> and the rest, and strikes his sword vpon London stone.</div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 Now is Mortemer Lord of this Citie,</div>
<div class="dverse">And now sitting vpon London stone, We command,</div>
<div class="dverse">That the first yeare of our raigne,</div>
<div class="dverse">The pissing Cundit run nothing but red wine.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daq005" id="lnum-daq005">5</a>
 And now hence forward, it shall be treason</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daq006" id="lnum-daq006">♦</a>
 For any that calles me any otherwise then</div>
<div class="dverse">Lord Mortemer.</div>

<div class="sd-entry">Enter a souldier.</div>

<div class="dverse1"><span class="sd-cn">Sould.</span>
 Iacke Cade, Iacke Cade.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daq009" id="lnum-daq009">♦</a>
 <span class="sd-cn">Cade.</span>
  Sounes, knocke him downe.   (They kill him.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daq010" id="lnum-daq010">10</a>
 <span class="sd-cn">Dicke.</span>
  My Lords, theirs an Army gathered togither</div>
<div class="dverse">Into Smythfield.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daq012" id="lnum-daq012">♦</a>
 <span class="sd-cn">Cade.</span>
  Come then, lets go fight with them,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daq013" id="lnum-daq013">♦</a>
 But first go on and set London Bridge a fire,</div>
<div class="dverse">And if you can, burne downe the Tower too.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daq015" id="lnum-daq015">15</a>
 Come lets away. <span class="sd-verseend"><i>Exet omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XVIII.
<span class="dnavigatenf">dar</span></h3>

Alarmes, and then <i>Mathew Goffe</i> is slaine, and all the rest with him. Then Enter <i>Iacke Cade</i> again, and his company.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dar001" id="lnum-dar001">♦</a>
 <span class="sd-cn">Cade.</span>
  So, sirs now go some and pull down the Sauoy,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dar002" id="lnum-dar002">♦</a>
 Others to the Innes of the Court, downe with them all.</div>

<div class="dverse1"><span class="sd-cn">Dicke.</span>
 I haue a sute vnto your Lordship.</div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 <i>Be</i> it a Lordship Dicke, and thou shalt haue it</div>
<div class="dverse"><span class="lnum">5</span>
 For that word.</div>

<div class="dverse1"><span class="sd-cn">Dicke.</span>
 That we may go burne all the Records,</div>
<div class="dverse">And that all writing may be put downe,</div>
<div class="dverse">And nothing vsde but the score and the Tally.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dar009" id="lnum-dar009">♦</a>
 <span class="sd-cn">Cade.</span>
 Dicke it shall be so, and henceforward all things shall be <span class="lnum">10</span>
 in common, and in Cheapeside shall my palphrey go to grasse. Why ist not a miserable thing, that of the skin of an innocent lamb <a class="lnum pginternal" href="#lnote-dar012" id="lnum-dar012">♦</a>
 should parchment be made, &amp; then with a litle blotting ouer with inke, a man should vndo himselfe.</div>
<div class="dprose1">Some saies tis the bees that sting, but I say, tis their waxe, for <span class="lnum">15</span>
 I am sure I neuer seald to any thing but once, and I was neuer mine owne man since.</div>

<div class="dverse1"><span class="sd-cn">Nicke.</span>
 But when shall we take vp those commodities</div>
<div class="dverse">Which you told vs of.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dar019" id="lnum-dar019">♦</a>
 <span class="sd-cn">Cade.</span>
  Marry he that will lustily stand to it,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dar020" id="lnum-dar020">20</a>
 Shall go with me, and take vp these commodities following:</div>
<div class="dverse">Item, a gowne, a kirtle, a petticoate, and a smocke.</div>

<div class="sd-entry">Enter <i>George</i>.</div>

<div class="dverse1"><span class="sd-cn">George.</span>
 My Lord, a prize, a prize, heres the Lord Say,</div>
<div class="dverse">Which sold the Townes in France.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dar024" id="lnum-dar024">♦</a>
 <span class="sd-cn">Cade.</span>
  Come hither thou Say, thou George, thou buckrum lord,</div>
<div class="dverse"><span class="lnum">25</span>
 What answere canst thou make vnto my mightinesse,</div>

<div class="dprose">For deliuering vp the townes in France to Mounsier bus mine cue, the Dolphin of France?</div>

<div class="dprose">
 And more then so, thou hast most traitorously erected a grammer schoole, to infect the youth of the realme, and against the Kings <span class="lnum">30</span>
 Crowne and dignitie, thou hast built vp a paper-mill, nay it wil be <a class="lnum pginternal" href="#lnote-dar031" id="lnum-dar031">♦</a>
 said to thy face, that thou kepst men in thy house that daily reades of bookes with red letters, and talkes of a Nowne and a Verbe, and <a class="lnum pginternal" href="#lnote-dar033" id="lnum-dar033">♦</a>
 such abhominable words as no Christian eare is able to endure it. <a class="lnum pginternal" href="#lnote-dar034" id="lnum-dar034">♦</a>
 And besides all that, thou hast appointed certaine Iustises of peace <span class="lnum">35</span>
 in euery shire to hang honest men that steale for their liuing, and because they could not reade, thou hast hung them vp: Onely for <a class="lnum pginternal" href="#lnote-dar037" id="lnum-dar037">♦</a>
 which cause they were most worthy to liue. Thou ridest on a foot-cloth doest thou not?</div>

<div class="dprose1"><span class="sd-cn">Say.</span>
 Yes, what of that?</div>

<div class="dprose1"><span class="lnum">40</span>
 <span class="sd-cn">Cade.</span>
 Marry I say, thou oughtest not to let thy horse weare a cloake, when an honester man then thy selfe, goes in his hose and doublet.</div>

<div class="dverse1"><span class="sd-cn">Say.</span>
 You men of Kent.</div>

<div class="dverse1"><span class="sd-cn">All.</span>
 Kent, what of Kent?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dar045" id="lnum-dar045">45</a>
 <span class="sd-cn">Say.</span>
 Nothing but <i>bona, terra</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dar046" id="lnum-dar046">♦</a>
 <span class="sd-cn">Cade.</span>
 <i>Bonum terum</i>, sounds whats that?</div>

<div class="dverse1"><span class="sd-cn">Dicke.</span>
 He speakes French.</div>

<div class="dverse1"><span class="sd-cn">Will.</span>
 No tis Dutch.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dar049" id="lnum-dar049">♦</a>
 <span class="sd-cn">Dicke.</span>
  No tis outtalian, I know it well inough.</div>

<div class="dverse1"><span class="lnum">50</span>
 <span class="sd-cn">Say.</span>
  Kent, in the Commentaries Cæsar wrote,</div>
<div class="dverse">Termde it the ciuel’st place of all this land,</div>
<div class="dverse">Then noble Country-men, heare me but speake,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dar053" id="lnum-dar053">♦</a>
 I sold not France, I lost not Normandie.</div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 But wherefore doest thou shake thy head so?</div>

<div class="dverse1"><span class="lnum">55</span>
 <span class="sd-cn">Say.</span>
  It is the palsie and not feare that makes me.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dar056" id="lnum-dar056">♦</a>
 <span class="sd-cn">Cade.</span>
 Nay thou nodst thy head, as who say, thou wilt be euen <a class="lnum pginternal" href="#lnote-dar057" id="lnum-dar057">♦</a>
 with me, if thou getst away, but ile make the sure inough, now I <a class="lnum pginternal" href="#lnote-dar058" id="lnum-dar058">♦</a>
 haue thee. Go take him to the standerd in Cheapeside and chop of his head, and then go to milende-greene, to sir Iames Cromer his <span class="lnum">60</span>
 sonne in law, and cut off his head too, and bring them to me vpon two poles presently. (Away with him. <span class="sd-proseend"><i>Exet</i> one or two, with the Lord <i>Say</i>.</span></div>

<div class="dverse">There shall not a noble man weare a head on his shoulders,</div>
<div class="dverse">But he shall paie me tribute for it.</div>
<div class="dverse">Nor there shal not a mayd be married, but he shal fee to me for her.</div>
<div class="dverse"><span class="lnum">65</span>
 Maydenhead or else, ile haue it my selfe,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dar066" id="lnum-dar066">♦</a>
 Marry I will that married men shall hold of me in capitie,</div>
<div class="dverse" id="lnum-dar067">And that their
 wiues shalbe as free as hart can thinke, or toong can (tell.</div>

<div class="sd-entry">Enter <i>Robin</i>.</div>

<div class="dverse1"><span class="sd-cn">Robin.</span>
 O Captaine, London bridge is a fire.</div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
 Runne to Billingsgate, and fetche pitch and flaxe and
 <a class="lnum pginternal" href="#lnote-dar070" id="lnum-dar070">70</a>
 squench it.</div>

<div class="sd-entry">Enter <i>Dicke</i> and a Sargiant.</div>

<div class="dprose1"><span class="sd-cn">Sargiant.</span>
 Iustice, iustice, I pray you sir, let me haue iustice of this fellow here.</div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 Why what has he done?</div>

<div class="dverse1"><span class="sd-cn">Sarg.</span>
 Alasse sir he has rauisht my wife.</div>

<div class="dverse1"><span class="lnum">75</span>
 <span class="sd-cn">Dicke.</span>
  Why my Lord he would haue rested me,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dar076" id="lnum-dar076">♦</a>
 And I went and and entred my Action in his wiues paper house.</div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 Dicke follow thy sute in her common place,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dar078" id="lnum-dar078">♦</a>
 You horson villaine, you are a Sargiant youle,</div>
<div class="dverse">Take any man by the throate for twelue pence,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dar080" id="lnum-dar080">80</a>
 And rest a man when hees at dinner,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dar081" id="lnum-dar081">♦</a>
 And haue him to prison ere the meate be out of his mouth.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dar082" id="lnum-dar082">♦</a>
 Go Dicke take him hence, cut out his toong for cogging,</div>
<div class="dverse">Hough him for running, and to conclude,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dar084" id="lnum-dar084">♦</a>
 Braue him with his owne mace. <span class="sd-verseend"><i>Exet</i> with the Sargiant.</span></div>

<div class="sd-entry">Enter two with the Lord <i>Sayes</i> head, and sir Iames Cromers, vpon two poles.</div>

<div class="dprose"><span class="lnum">85</span> kisse togither. So, come carry them before me, and at euery lanes ende, let them</div>

<div class="sd-entry">Enter the Duke of <i>Buckingham</i>, and Lord <i>Clifford</i> the Earle of <i>Comberland</i>.</div>

<div class="dverse1"><span class="sd-cn">Clifford.</span>
 Why country-men and warlike friends of Kent,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dar088" id="lnum-dar088">♦</a>
 What meanes this mutinous rebellions,</div>
<div class="dverse">That you in troopes do muster thus your selues,</div>
<div class="dverse"><span class="lnum">90</span>
 Vnder the conduct of this Traitor Cade?</div>
<div class="dverse">To rise against your soueraigne Lord and King,</div>
<div class="dverse">Who mildly hath his pardon sent to you,</div>
<div class="dverse">If you forsake this monstrous Rebell here?</div>
<div class="dverse">If honour be the marke whereat you aime,</div>
<div class="dverse"><span class="lnum">95</span>
 Then haste to France that our forefathers wonne,</div>
<div class="dverse">And winne againe that thing which now is lost,</div>
<div class="dverse">And leaue to seeke your Countries ouerthrow.</div>

<div class="dverse1"><span class="sd-cn">All.</span>
 A Clifford, a Clifford. <span class="sd-verseend">They forsake Cade.</span></div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 Why how now, will you forsake your generall,</div>
<div class="dverse"><span class="lnum">100</span>
 And ancient freedome which you haue possest?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dar101" id="lnum-dar101">♦</a>
 To bend your neckes vnder their seruile yokes,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dar102" id="lnum-dar102">♦</a>
 Who if you stir, will straightwaies hang you vp,</div>
<div class="dverse">But follow me, and you shall pull them downe,</div>
<div class="dverse">And make them yeeld their liuings to your hands.</div>

<div class="dverse1"><span class="lnum">105</span>
 <span class="sd-cn">All.</span>
 A Cade, a Cade.
 <span class="sd-verseend">They runne to <i>Cade</i> againe.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dar106" id="lnum-dar106">♦</a>
 <span class="sd-cn">Cliff.</span>
  Braue warlike friends heare me but speak a word,</div>
<div class="dverse">Refuse not good whilst it is offered you,</div>
<div class="dverse">The King is mercifull, then yeeld to him,</div>
<div class="dverse">And I my selfe will go along with you,</div>
<div class="dverse"><span class="lnum">110</span>
 To Winsore Castle whereas the King abides,</div>
<div class="dverse">And on mine honour you shall haue no hurt.</div>

<div class="dverse1"><span class="sd-cn">All.</span>
 A Clifford, a Clifford, God saue the King.</div>

<div class="dverse1"><span class="sd-cn">Cade.</span>
 How like a feather is this rascall company</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dar114" id="lnum-dar114">♦</a>
 Blowne euery way,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dar115" id="lnum-dar115">115</a>
 But that they may see there want no valiancy in me,</div>
<div class="dverse">My staffe shall make way through the midst of you,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dar117" id="lnum-dar117">♦</a>
 And so a poxe take you all. <span class="sd-verseend">He runs through them with his staffe, and flies away.</span></div>

<div class="dverse1"><span class="sd-cn">Buc.</span>
 Go some and make after him, and proclaime,</div>
<div class="dverse">That those that can bring the head of Cade,</div>
<div class="dverse"><span class="lnum">120</span>
 Shall haue a thousand Crownes for his labour.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dar121" id="lnum-dar121">♦</a>
 Come march away. <span class="sd-verseend"><i>Exet omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XIX.
<span class="dnavigatenf">das</span></h3>

Enter King <i>Henry</i> and the Queene, and <i>Somerset</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-das001" id="lnum-das001">♦</a>
 <span class="sd-cn">King.</span>
  Lord Somerset, what newes here you of the Rebell Cade?</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 This, my gratious Lord, that the Lord Say is don to death,</div>
<div class="dverse">And the Citie is almost sackt.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-das004" id="lnum-das004">♦</a>
 <span class="sd-cn">King.</span>
  Gods will be done, for as he hath decreede, so must it be:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-das005" id="lnum-das005">5</a>
 And be it as he please, to stop the pride of those rebellious men.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 Had the noble Duke of Suffolke bene aliue,</div>
<div class="dverse">The Rebell Cade had bene supprest ere this,</div>
<div class="dverse">And all the rest that do take part with him.</div>

<div class="sd-entry">Enter the Duke of <i>Buckingham</i> and <i>Clifford</i>, with the Rebels, with halters about their necks.</div>

<div class="dverse1"><span class="sd-cn">Cliff.</span>
 Long liue King Henry, Englands lawfull King,</div>
<div class="dverse"><span class="lnum">10</span>
 Loe here my Lord, these Rebels are subdude,</div>
<div class="dverse">And offer their liues before your highnesse feete.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-das012" id="lnum-das012">♦</a>
 <span class="sd-cn">King.</span>
  But tell me Clifford, is there Captaine here.</div>

<div class="dprose1"><span class="sd-cn">Clif.</span>
 No, my gratious Lord, he is fled away, but proclamations are sent forth, that he that can but bring his head, shall haue a thousand <span class="lnum">15</span>
 crownes. But may it please your Maiestie, to pardon these <a class="lnum pginternal" href="#lnote-das016" id="lnum-das016">♦</a>
 their faults, that by that traitors meanes were thus misled.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Stand vp you simple men, and giue God praise,</div>
<div class="dverse">For you did take in hand you know not what,</div>
<div class="dverse">And go in peace obedient to your King,</div>
<div class="dverse"><span class="lnum">20</span>
 And liue as subiects, and you shall not want,</div>
<div class="dverse">Whilst Henry liues, and weares the English Crowne.</div>

<div class="dverse1"><span class="sd-cn">All.</span>
 God saue the King, God saue the King.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Come let vs hast to London now with speed,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-das024" id="lnum-das024">♦</a>
 That solemne prosessions may be sung,</div>
<div class="dverse"><span class="lnum">25</span>
 In laud and honour of the God of heauen,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-das026" id="lnum-das026">♦</a>
 And triumphs of this happie victorie. <span class="sd-verseend">(<i>Exet omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XX.
<span class="dnavigatenf">dat</span></h3>

Enter <i>Iacke Cade</i> at one doore, and at the other, maister <i>Alexander Eyden</i> and his men, and <i>Iack Cade</i> lies downe picking of hearbes and eating them.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dat001" id="lnum-dat001">♦</a>
 <span class="sd-cn">Eyden.</span>
  Good Lord how pleasant is this country life,</div>
<div class="dverse">This litle land my father left me here,</div>
<div class="dverse">With my contented minde serues me as well,</div>
<div class="dverse">As all the pleasures in the Court can yeeld,</div>
<div class="dverse"><span class="lnum">5</span>
 Nor would I change this pleasure for the Court.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dat006" id="lnum-dat006">♦</a>
 <span class="sd-cn">Cade.</span>
 Sounes, heres the Lord of the soyle, Stand villaine, thou wilt betraie mee to the King, and get a thousand crownes for <a class="lnum pginternal" href="#lnote-dat008" id="lnum-dat008">♦</a>
 my head, but ere thou goest, ile make thee eate yron like an Astridge, and swallow my sword like a great pinne.</div>

<div class="dverse1"><span class="lnum">10</span>
 <span class="sd-cn">Eyden.</span>
  Why sawcy companion, why should I betray thee?</div>
<div class="dverse">Ist not inough that thou hast broke my hedges,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dat012" id="lnum-dat012">♦</a>
 And enterd into my ground without the leaue of me the owner,</div>
<div class="dverse">But thou wilt braue me too.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dat014" id="lnum-dat014">♦</a>
 <span class="sd-cn">Cade.</span>
 Braue thee and beard thee too, by the best blood of the <span class="lnum">15</span>
 Realme, looke on me well, I haue eate no meate this fine dayes, yet <a class="lnum pginternal" href="#lnote-dat016" id="lnum-dat016">♦</a>
 and I do not leaue thee and thy fine men as dead as a doore nayle, I pray God I may neuer eate grasse more.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dat018" id="lnum-dat018">♦</a>
 <span class="sd-cn">Eyden.</span>
 Nay, it neuer shall be saide whilst the world doth stand, that Alexander Eyden an Esquire of Kent, tooke oddes to combat <span class="lnum">20</span>
 with a famisht man, looke on me, my limmes are equall vnto thine, and <a class="lnum pginternal" href="#lnote-dat021" id="lnum-dat021">♦</a>
 euery way as big, then hand to hand, ile combat thee. Sirrha <a class="lnum pginternal" href="#lnote-dat022" id="lnum-dat022">♦</a>
 fetch me weopons, and stand you all aside.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dat023" id="lnum-dat023">♦</a>
 <span class="sd-cn">Cade.</span>
 Now sword, if thou doest not hew this burly-bond churle <a class="lnum pginternal" href="#lnote-dat024" id="lnum-dat024">♦</a>
 into chines of beefe, I beseech God thou maist fal into some smiths <a class="lnum pginternal" href="#lnote-dat025" id="lnum-dat025">25</a>
 hand, and be turnd to hob-nailes.</div>

<div class="dverse1"><span class="sd-cn">Eyden.</span>
 Come on thy way. <span class="sd-verseend">(They fight, and <i>Cade</i> fals downe.</span></div>

<div class="dprose1"><span class="sd-cn">Cade.</span>
 Oh villaine, thou hast slaine the floure of Kent for chiualrie, but it is famine &amp; not thee that has done it, for come ten thousand diuels, and giue me but the ten meales that I wanted this fiue daies, and ile fight with you all, and so a poxe rot thee, for Iack Cade must die. <span class="sd-proseend">(He dies.</span></div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-dat032" id="lnum-dat032">♦</a>
 <span class="sd-cn">Eyden.</span>
 Iack Cade, &amp; was it that monstrous Rebell which I haue <a class="lnum pginternal" href="#lnote-dat033" id="lnum-dat033">♦</a>
 slaine. Oh sword ile honour thee for this, and in my chamber shalt thou hang as a monument to after age, for this great seruice thou <a class="lnum pginternal" href="#lnote-dat035" id="lnum-dat035">35</a>
 hast done to me. He drag him hence, and with my sword cut off his <a class="lnum pginternal" href="#lnote-dat036" id="lnum-dat036">♦</a>
 head, and beare it <span class="sd-proseend"><i>Exet.</i></span><div class="clearboth"></div></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XXI.
<span class="dnavigatenf">dau</span></h3>

Enter the Duke of <i>Yorke</i> with Drum and souldiers.</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 In Armes from Ireland comes Yorke amaine,</div>
<div class="dverse">Ring belles aloud, bonfires perfume the ayre,</div>
<div class="dverse">To entertaine faire Englands royall King.</div>
<div class="dverse">Ah <i>Sancta Maiesta</i>, who would not buy thee deare?</div>

<div class="sd-entry">Enter the Duke of <i>Buckingham</i>.</div>

<div class="dverse"><a class="lnum pginternal" href="#lnote-dau005" id="lnum-dau005">5</a>
 But soft, who comes here <i>Buckingham</i>, what newes with him?</div>

<div class="dverse1"><span class="sd-cn">Buc.</span>
 Yorke, if thou meane well, I greete thee so.</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 Humphrey of Buckingham, welcome I sweare:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dau008" id="lnum-dau008">♦</a>
 What comes thou in loue or as a Messenger?</div>

<div class="dverse1"><span class="sd-cn">Buc.</span>
 I come as a Messenger from our dread Lord and soueraign,</div>
<div class="dverse"><span class="lnum">10</span>
 Henry. To know the reason of these Armes in peace?</div>
<div class="dverse">Or that thou being a subiect as I am,</div>
<div class="dverse">Shouldst thus approach so neare with colours spred,</div>
<div class="dverse">Whereas the person of the King doth keepe?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dau014" id="lnum-dau014">♦</a>
 <span class="sd-cn">Yorke.</span>
  A subiect as he is.</div>
<div class="dverse"><span class="lnum">15</span>
 Oh how I hate these spitefull abiect termes,</div>
<div class="dverse">But Yorke dissemble, till thou meete thy sonnes,</div>
<div class="dverse">Who now in Armes expect their fathers sight,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dau018" id="lnum-dau018">♦</a>
 And not farre hence I know they cannot be.</div>
<div class="dverse">Humphrey Duke of Buckingham, pardon me,</div>
<div class="dverse"><span class="lnum">20</span>
 That I answearde not at first, my mind was troubled,</div>
<div class="dverse">I came to remoue that monstrous Rebell Cade,</div>
<div class="dverse">And heaue proud Somerset from out the Court,</div>
<div class="dverse">That basely yeelded vp the Townes in France.</div>

<div class="dverse1"><span class="sd-cn">Buc.</span>
 Why that was presumption on thy behalfe,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dau025" id="lnum-dau025">25</a>
 But if it be no otherwise but so,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dau026" id="lnum-dau026">♦</a>
 The King doth pardon thee, and granst to thy request,</div>
<div class="dverse">And Somerset is sent vnto the Tower.</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 Vpon thine honour is it so?</div>

<div class="dverse1"><span class="sd-cn">Buc.</span>
 Yorke, he is vpon mine honour.</div>

<div class="dverse1"><span class="lnum">30</span>
 <span class="sd-cn">York.</span>
  Then before thy face, I here dismisse my troopes,</div>
<div class="dverse">Sirs, meete me to morrow in saint Georges fields,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dau032" id="lnum-dau032">♦</a>
 And there you shall receiue your paie of me. <span class="sd-verseend"><i>Exet</i> souldiers.</span></div>

<div class="dverse1"><span class="sd-cn">Buc.</span>
 Come York, thou shalt go speake vnto the King,</div>
<div class="dverse">But see, his grace is comming to meete with vs.</div>

<div class="sd-entry">Enter King <i>Henry</i>.</div>

<div class="dverse1"><span class="lnum">35</span>
 <span class="sd-cn">King.</span>
  How now Buckingham, is Yorke friends with vs,</div>
<div class="dverse">That thus thou bringst him hand in hand with thee?</div>

<div class="dverse1"><span class="sd-cn">Buc.</span>
 He is my Lord, and hath dischargde his troopes</div>
<div class="dverse">Which came with him, but as your grace did say,</div>
<div class="dverse">To heaue the Duke of Somerset from hence,</div>
<div class="dverse"><span class="lnum">40</span>
 And to subdue the Rebels that were vp.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Then welcome cousin Yorke, giue me thy hand,</div>
<div class="dverse">And thankes for thy great seruice done to vs,</div>
<div class="dverse">Against those traitorous Irish that rebeld.</div>

<div class="sd-entry">Enter maister <i>Eyden</i> with <i>Iacke Cades</i> head.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dau044" id="lnum-dau044">♦</a>
 <span class="sd-cn">Eyden.</span>
  Long liue Henry in triumphant peace,</div>
<div class="dverse"><span class="lnum">45</span>
 Lo here my Lord vpon my bended knees,</div>
<div class="dverse">I here present the traitorous head of Cade,</div>
<div class="dverse">That hand to hand in single fight I slue.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 First thanks to heauen, &amp; next to thee my friend,</div>
<div class="dverse">That hast subdude that wicked traitor thus.</div>
<div class="dverse"><span class="lnum">50</span>
 O let me see that head that in his life,</div>
<div class="dverse">Did worke me and my land such cruell spight,</div>
<div class="dverse">A visage sterne, cole blacke his curled locks,</div>
<div class="dverse">Deepe trenched furrowes in his frowning brow,</div>
<div class="dverse">Presageth warlike humors in his life.</div>
<div class="dverse"><span class="lnum">55</span>
 Here take it hence and thou for thy reward,</div>
<div class="dverse">Shalt be immediatly created Knight.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dau057" id="lnum-dau057">♦</a>
 Kneele downe my friend, and tell me whats thy name?</div>

<div class="dverse1"><span class="sd-cn">Eyden.</span>
 Alexander Eyden, if it please your grace,</div>
<div class="dverse">A poore Esquire of Kent.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dau060" id="lnum-dau060">60</a>
 <span class="sd-cn">King.</span>
  Then rise vp sir Alexander Eyden knight,</div>
<div class="dverse">And for thy maintenance, I freely giue</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dau062" id="lnum-dau062">♦</a>
 A thousand markes a yeare to maintaine thee,</div>
<div class="dverse">Beside the firme reward that was proclaimde,</div>
<div class="dverse">For those that could performe this worthie act,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dau065" id="lnum-dau065">65</a>
 And thou shalt waight vpon the person of the king.</div>

<div class="dverse1"><span class="sd-cn">Eyden.</span>
 I humbly thank your grace, and I no longer liue,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dau067" id="lnum-dau067">♦</a>
 Then I proue iust and loyall to my king. <span class="sd-verseend">(<i>Exet.</i></span></div>

<div class="sd-entry">Enter the Queene with the Duke of <i>Somerset</i>.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 O Buckingham see where Somerset comes,</div>
<div class="dverse">Bid him go hide himselfe till Yorke be gone.</div>

<div class="dverse1"><span class="lnum">70</span>
 <span class="sd-cn">Queene.</span>
  He shall not hide himselfe for feare of Yorke,</div>
<div class="dverse">But beard and braue him proudly to his face.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dau072" id="lnum-dau072">♦</a>
 <span class="sd-cn">Yorke.</span>
  Whose that, proud Somerset at libertie?</div>
<div class="dverse">Base fearefull Henry that thus dishonor’st me,</div>
<div class="dverse">By heauen, thou shalt not gouerne ouer me:</div>
<div class="dverse"><span class="lnum">75</span>
 I cannot brooke that Traitors presence here,</div>
<div class="dverse">Nor will I subiect be to such a King,</div>
<div class="dverse">That knowes not how to gouerne nor to rule,</div>
<div class="dverse">Resigne thy Crowne proud Lancaster to me,</div>
<div class="dverse">That thou vsurped hast so long by force,</div>
<div class="dverse"><span class="lnum">80</span>
 For now is Yorke resolu’d to claim his owne,</div>
<div class="dverse">And rise aloft into faire Englands Throane.</div>

<div class="dverse1"><span class="sd-cn">Somer.</span>
 Proud Traitor, I arest thee on high treason,</div>
<div class="dverse">Against thy soueraigne Lord, yeeld thee false Yorke,</div>
<div class="dverse">For here I sweare, thou shalt vnto the Tower,</div>
<div class="dverse"><span class="lnum">85</span>
 For these proud words which thou hast giuen the king.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dau086" id="lnum-dau086">♦</a>
 <span class="sd-cn">Yorke.</span>
  Thou art deceiued, my sonnes shalbe my baile,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dau087" id="lnum-dau087">♦</a>
 And send thee there in dispight of him.</div>
<div class="dverse">Hoe, where are you boyes?</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 Call Clifford hither presently.</div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XXII.
<span class="dnavigatenf">dav</span></h3>

Enter the Duke of <i>Yorkes</i> sonnes, <i>Edward</i> the Earle of <i>March</i>, and crook-backe <i>Richard</i>, at the one doore, with Drumme and soldiers, and at the other doore, enter <i>Clifford</i> and his sonne, with Drumme and souldiers, and <i>Clifford</i> kneeles to <i>Henry</i>, and speakes.</div>

<div class="dverse1"><span class="sd-cn">Cliff.</span>
 Long liue my noble Lord, and soueraigne King.</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 We thank thee Clifford.</div>
<div class="dverse">Nay, do not affright vs with thy lookes,</div>
<div class="dverse">If thou didst mistake, we pardon thee, kneele againe.</div>

<div class="dverse1"><span class="lnum">5</span>
 <span class="sd-cn">Cliff.</span>
  Why, I did no way mistake, this is my King.</div>
<div class="dverse">What is he mad? to Bedlam with him.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dav007" id="lnum-dav007">♦</a>
 <span class="sd-cn">King.</span>
  I, a bedlam frantike humor driues him thus</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dav008" id="lnum-dav008">♦</a>
 To leauy Armes against his lawfull King.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dav009" id="lnum-dav009">♦</a>
 <span class="sd-cn">Clif.</span>
  Why doth not your grace send him to the Tower?</div>

<div class="dverse1"><span class="lnum">10</span>
 <span class="sd-cn">Queene.</span>
  He is arested, but will not obey,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dav011" id="lnum-dav011">♦</a>
 His sonnes he saith, shall be his baile.</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 How say you boyes, will you not?</div>

<div class="dverse1"><span class="sd-cn">Edward.</span>
 Yes noble father, if our words will serue.</div>

<div class="dverse1"><span class="sd-cn">Richard.</span>
 And if our words will not, our swords shall.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">Yorke.</span>
  Call hither to the stake, my two rough beares.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Call Buckingham, and bid him Arme himselfe.</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 Call Buckingham and all the friends thou hast,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dav018" id="lnum-dav018">♦</a>
 Both thou and they, shall curse this fatall houre.</div>

<div class="sd-entry">Enter at one doore, the Earles of <i>Salsbury</i> and <i>Warwicke</i>, with Drumme and souldiers. And at the other, the Duke of <i>Buckingham</i>, with Drumme and souldiers.</div>

<div class="dverse1"><span class="sd-cn">Cliff.</span>
 Are these thy beares? weele bayte them soone,</div>
<div class="dverse">Dispight of thee, and all the friends thou hast. ·dav20·</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 You had best go dreame againe,</div>
<div class="dverse">To keepe you from the tempest of the field.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 I am resolu’d to beare a greater storme,</div>
<div class="dverse">Then any thou canst coniure vp to day,</div>
<div class="dverse"><span class="lnum">25</span>
 And that ile write vpon thy Burgonet,</div>
<div class="dverse">Might I but know thee by thy houshold badge.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Now by my fathers age, old Neuels crest,</div>
<div class="dverse">The Rampant Beare chaind to the ragged staffe,</div>
<div class="dverse">This day ile weare aloft my burgonet,</div>
<div class="dverse"><span class="lnum">30</span>
 As on a mountaine top the Cædar showes,</div>
<div class="dverse">That keepes his leaues in spight of any storme,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dav032" id="lnum-dav032">♦</a>
 Euen to affright the with the view thereof.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 And from thy burgonet will I rend the beare,</div>
<div class="dverse">And tread him vnderfoote with all contempt,</div>
<div class="dverse"><span class="lnum">35</span>
 Dispight the Beare-ward that protects him so.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dav036" id="lnum-dav036">♦</a>
 <span class="sd-cn">Yoong Clif.</span>
  And so renowmed soueraigne to Armes,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-dav037" id="lnum-dav037">♦</a>
 To quell these Traitors and their compleases.</div>

<div class="dverse1"><span class="sd-cn">Richard.</span>
 Fie, Charitie for shame, speake it not in spight,</div>
<div class="dverse">For you shall sup with Iesus Christ to night.</div>

<div class="dverse1"><span class="lnum">40</span>
 <span class="sd-cn">Yoong Clif.</span>
  Foule Stigmaticke thou canst not tell.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-dav041" id="lnum-dav041">♦</a>
 <span class="sd-cn">Rich.</span>
 No, for if not in heauen, youle surely sup in hell. <span class="sd-verseend"><i>Exet omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XXIII.
<span class="dnavigatenf">daw</span></h3>

Alarmes to the battaile, and then enter the Duke of <i>Somerset</i> and <i>Richard</i> fighting, and <i>Richard</i> kils him vnder the signe of the Castle in saint <i>Albones</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daw001" id="lnum-daw001">♦</a>
 <span class="sd-cn">Rich.</span>
  So Lie thou there, and breathe thy last.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daw002" id="lnum-daw002">♦</a>
 Whats here, the signe of the Castle?</div>
<div class="dverse">Then the prophesie is come to passe,</div>
<div class="dverse">For Somerset was forewarned of Castles,</div>
<div class="dverse"><span class="lnum">5</span>
 The which he alwaies did obserue.</div>
<div class="dverse">And now behold, vnder a paltry Ale-house signe,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daw007" id="lnum-daw007">♦</a>
 The Castle in saint Albones,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daw008" id="lnum-daw008">♦</a>
 Somerset hath made the Wissard famous by his death. <span class="sd-verseend"><i>Exet.</i></span></div>

<div class="sd-entry">Alarme again, and enter the Earle of <i>Warwicke</i> alone.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Clifford of Comberland, tis Warwicke calles,</div>
<div class="dverse"><span class="lnum">10</span>
 And if thou doest not hide thee from the Beare,</div>
<div class="dverse">Now whilst the angry Trompets sound Alarmes,</div>
<div class="dverse">And dead mens cries do fill the emptie aire:</div>
<div class="dverse">Clifford I say, come forth and fight with me,</div>
<div class="dverse">Proud Northerne Lord, Clifford of Comberland,</div>
<div class="dverse"><span class="lnum">15</span>
 Warwicke is hoarse with calling thee to Armes.
 <span class="sd-verseend">Clifford speakes within.</span></div>

<div class="dprose">Warwicke stand still, and view the way that Clifford hewes with his murthering Curtel-axe, through the fainting troopes to finde thee out.</div>

<div class="dprose">Warwicke stand still, and stir not till I come.</div>

<div class="sd-entry">Enter <i>Yorke</i>.</div>

<div class="dverse1"><span class="lnum">20</span>
 <span class="sd-cn">War.</span>
  How now my Lord, what a foote?</div>
<div class="dverse">Who kild your horse?</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 The deadly hand of Clifford. Noble Lord,</div>
<div class="dverse">Fiue horse this day slaine vnder me,</div>
<div class="dverse">And yet braue Warwicke I remaine aliue,</div>
<div class="dverse"><span class="lnum">25</span>
 But I did kill his horse he lou’d so well,</div>
<div class="dverse">The boniest gray that ere was bred in North.</div>

<div class="sd-entry">Enter <i>Clifford</i>, and <i>Warwicke</i> offers to fight with him.</div>

<div class="dverse">Hold Warwicke, and seeke thee out some other chase,</div>
<div class="dverse">My selfe will hunt this deare to death.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daw029" id="lnum-daw029">♦</a>
 <span class="sd-cn">War.</span>
  Braue Lord, tis for a Crowne thou fights,</div>
<div class="dverse"><span class="lnum">30</span>
 Clifford farewell, as I entend to prosper well to day,</div>
<div class="dverse">It grieues my soule to leaue thee vnassaild. <span class="sd-verseend"><i>Exet Warwicke.</i></span></div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 Now Clifford, since we are singled here alone,</div>
<div class="dverse">Be this the day of doome to one of vs,</div>
<div class="dverse">For now my heart hath sworne immortall hate</div>
<div class="dverse"><span class="lnum">35</span>
 To thee, and all the house of Lancaster.</div>

<div class="dverse1"><span class="sd-cn">Cliffood.</span>
 And here I stand, and pitch my foot to thine,</div>
<div class="dverse">Vowing neuer to stir, till thou or I be slaine.</div>
<div class="dverse">For neuer shall my heart be safe at rest,</div>
<div class="dverse">Till I haue spoyld the hatefull house of Yorke. <span class="sd-verseend">Alarmes, and they fight, and <i>Yorke</i> kils <i>Clifford</i>.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-daw040" id="lnum-daw040">40</a>
 <span class="sd-cn">Yorke.</span>
  Now Lancaster sit sure, thy sinowes shrinke,</div>
<div class="dverse">Come fearefull Henry grouelling on thy face,</div>
<div class="dverse">Yeeld vp thy Crowne vnto the Prince of Yorke. <span class="sd-verseend"><i>Exet Yorke.</i></span></div>

<div class="sd-entry">Alarmes, then enter yoong <i>Clifford</i> alone.</div>

<div class="dverse1"><span class="sd-cn">Yoong Clifford.</span>
 Father of Comberland,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daw044" id="lnum-daw044">♦</a>
 Where may I seeke my aged father forth?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daw045" id="lnum-daw045">45</a>
 O! dismall sight, see where he breathlesse lies,</div>
<div class="dverse">All smeard and weltred in his luke-warme blood,</div>
<div class="dverse">Ah, aged pillar of all Comberlands true house,</div>
<div class="dverse">Sweete father, to thy murthred ghoast I sweare,</div>
<div class="dverse">Immortall hate vnto the house of Yorke,</div>
<div class="dverse">Nor neuer shall I sleepe secure one night,</div>
<div class="dverse">Till I haue furiously reuengde thy death,</div>
<div class="dverse">And left not one of them to breath on earth. <span class="sd-verseend">He takes him vp on his backe.</span></div>

<div class="dverse">And thus as old Ankyses sonne did beare</div>
<div class="dverse">His aged father on his manly backe,</div>
<div class="dverse"><span class="lnum">55</span>
 And fought with him against the bloodie Greeks,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daw056" id="lnum-daw056">♦</a>
 Euen so will I. But staie, heres one of them,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daw057" id="lnum-daw057">♦</a>
 To whom my soule hath sworne immortall hate.</div>

<div class="sd-entry">Enter <i>Richard</i>, and then <i>Clifford</i> laies downe his father, fights with him, and <i>Richard</i> flies away againe.</div>

<div class="dverse"><a class="lnum pginternal" href="#lnote-daw058" id="lnum-daw058">♦</a>
 Out crooktbacke villaine, get thee from my sight.</div>
<div class="dverse">But I will after thee, and once againe</div>
<div class="dverse"><span class="lnum">60</span>
 When I haue borne my father to his Tent,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daw061" id="lnum-daw061">♦</a>
 Ile trie my fortune better with thee yet. <span class="sd-verseend"><i>Exet</i> yoong <i>Clifford</i> with his father.</span></div>

<div class="sd-entry">Alarmes againe, and then enter three or foure, bearing the Duke of <i>Buckingham</i> wounded to his Tent.</div>

<div class="sd-entry">Alarmes still, and then enter the King and Queene.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 Away my Lord, and flie to London straight,</div>
<div class="dverse">Make hast, for vengeance comes along with them,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daw064" id="lnum-daw064">♦</a>
 Come stand not to expostulate, lets go.</div>

<div class="dverse1"><span class="lnum">65</span>
 <span class="sd-cn">King.</span>
  Come then faire Queene, to London let vs hast,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daw066" id="lnum-daw066">♦</a>
 And sommon a Parlament with speede,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daw067" id="lnum-daw067">♦</a>
 To stop the fury of these dyre euents. <span class="sd-verseend"><i>Exet</i> King and Queene.</span></div>

<div class="sd-entry">Alarmes, and then a flourish, and enter the Duke of <i>Yorke</i> and <i>Richard</i>.</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 How now boyes, fortunate this fight hath bene,</div>
<div class="dverse">I hope to vs and ours, for Englands good,</div>
<div class="dverse"><span class="lnum">70</span>
 And our great honour, that so long we lost,</div>
<div class="dverse">Whilst faint-heart Henry did vsurpe our rights:</div>
<div class="dverse">But did you see old Salsbury, since we</div>
<div class="dverse">With bloodie mindes did buckle with the foe,</div>
<div class="dverse">I would not for the losse of this right hand,</div>
<div class="dverse"><span class="lnum">75</span>
 That ought but well betide that good old man.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 My Lord, I saw him in the thickest throng,</div>
<div class="dverse">Charging his Lance with his old weary armes,</div>
<div class="dverse">And thrise I saw him beaten from his horse,</div>
<div class="dverse">And thrise this hand did set him vp againe,</div>
<div class="dverse"><span class="lnum">80</span>
 And still he fought with courage gainst his foes,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daw081" id="lnum-daw081">♦</a>
 The boldest sprited man that ere mine eyes beheld.</div>

<div class="sd-entry">Enter <i>Salsbbury</i> and <i>Warwicke</i>.</div>

<div class="dverse1"><span class="sd-cn">Edward.</span>
 See noble father, where they both do come,</div>
<div class="dverse">The onely props vnto the house of Yorke.</div>

<div class="dverse1"><span class="sd-cn">Sals.</span>
 Well hast thou fought this day, thou valiant Duke,</div>
<div class="dverse"><span class="lnum">85</span>
 And thou braue bud of Yorkes encreasing house,</div>
<div class="dverse">The small remainder of my weary life,</div>
<div class="dverse">I hold for thee, for with thy warlike arme,</div>
<div class="dverse">Three times this day thou hast preseru’d my life.</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 What say you Lords, the King is fled to London?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daw090" id="lnum-daw090">90</a>
 There as I here to hold a Parlament.</div>
<div class="dverse">What saies Lord Warwicke, shall we after them?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 After them, nay before them if we can.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daw093" id="lnum-daw093">♦</a>
 Now by my faith Lords, twas a glorious day,</div>
<div class="dverse">Saint Albones battaile wonne by famous Yorke,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daw095" id="lnum-daw095">95</a>
 Shall be eternest in all age to come.</div>
<div class="dverse">Sound Drummes and Trumpets, and to London all,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-daw097" id="lnum-daw097">♦</a>
 And more such daies as these to vs befall.
 <span class="sd-verseend"><i>Exet omnes.</i></span></div>

<div class="toppadb">FINIS.</div>

<div class="toppadb">London.</div>

<div class="endtext">Printed by Thomas Creed, for Thomas
Millington, and are to be sold at his Shop vnder Saint Peters
Church in Cornwall.</div>

<div>1594.</div>

<div class="right toppadb">
<a href="#idtoc" class="pginternal">toc</a></div>

<ul>
<li><h3 class="h3main" title="LINENOTES to the First Part of the Contention, &amp;c." id="iddln">
LINENOTES TO THE FIRST PART OF THE CONTENTION, &amp;c.</h3></li>

<li><a class="fnlabel pginternal" href="#lnum-daa008" id="lnote-daa008">daa008</a>
<i>then the</i>] <span class="nowrap">Q<sub>1</sub></span> <span class="nowrap">Q<sub>2</sub>.</span> <i>twenty</i> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-daa030" id="lnote-daa030">daa030</a>
<i>her speech</i>] <span class="nowrap">Q<sub>1</sub></span> <span class="nowrap">Q<sub>3</sub>.</span> <i>speech</i> <span class="nowrap">Q<sub>2</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-daa032" id="lnote-daa032">daa032</a>
